(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,68394,e=>{"use strict";var t=e.i(24180);let i=[{id:"rw-wic-01",skill:"Craft and Structure",topic:"Words in Context",difficulty:"easy",context:"When the archaeologist Kemal Akishev opened the Issyk kurgan in 1969, he found a burial so richly appointed that it reframed what scholars assumed about Saka metalwork. The gold plaques covering the warrior's costume were not crude ornaments but _____ objects, each animal figure cut with a precision that implied generations of accumulated technique.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["accidental","sophisticated","enormous","inexpensive"],answer:{kind:"choice",correct:1},explain:{en:'The blank contrasts with "crude ornaments" and is supported by "precision" and "generations of accumulated technique." Only "sophisticated" captures refined skill.',ru:"Пропуск противопоставлен «crude ornaments» и поддержан словами «precision» и «generations of accumulated technique». Только «sophisticated» передаёт отточенное мастерство."},trap:{en:'"Enormous" describes size, not skill — the passage never discusses how big the plaques were.',ru:"«Enormous» — про размер, а не про мастерство: о величине пластин в тексте нет ни слова."}},{id:"rw-wic-02",skill:"Craft and Structure",topic:"Words in Context",difficulty:"medium",context:"Critics initially dismissed Abai Kunanbaiuly's Book of Words as a miscellany, a collection too varied in subject to hold together. Later readers found that judgment _____: the apparent scattering of topics turns out to follow a single argument about moral self-examination, pursued from one angle after another.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["premature","conventional","generous","ambiguous"],answer:{kind:"choice",correct:0},explain:{en:'Later readers discovered an underlying unity the early critics missed, so the early judgment was made too soon — "premature."',ru:"Поздние читатели нашли единство, которого ранние критики не увидели, — значит, суждение было вынесено слишком рано: «premature»."},trap:{en:'"Generous" reverses the logic: the early judgment was too harsh, not too kind.',ru:"«Generous» переворачивает логику: раннее суждение было слишком суровым, а не слишком мягким."}},{id:"rw-wic-03",skill:"Craft and Structure",topic:"Words in Context",difficulty:"hard",context:"In her study of steppe pastoralism, the historian argues that mobility was not a failure to settle but a deliberate economic strategy. Her account is nonetheless _____ about its limits: she concedes that the archaeological record for the eighth century is too thin to establish whether the pattern she describes held across the whole region.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["evasive","candid","dismissive","indifferent"],answer:{kind:"choice",correct:1},explain:{en:'"She concedes" signals open acknowledgement of a weakness. "Candid" means frank about limitations; "nonetheless" marks the contrast with her confident main claim.',ru:"«She concedes» — это открытое признание слабого места. «Candid» значит «откровенный о своих ограничениях»; «nonetheless» отмечает контраст с уверенным основным тезисом."},trap:{en:'"Evasive" is the opposite: someone evasive would hide the gap in the record, not concede it.',ru:"«Evasive» — противоположность: уклончивый автор скрыл бы пробел в данных, а не признал его."}},{id:"rw-wic-04",skill:"Craft and Structure",topic:"Words in Context",difficulty:"medium",context:"Ecologists studying the Aral basin have had to work with data that is _____ at best: Soviet-era hydrological records were collected inconsistently, and satellite coverage of the region only becomes reliable after 1985.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["abundant","fragmentary","controversial","theoretical"],answer:{kind:"choice",correct:1},explain:{en:'Inconsistent collection plus a late start for reliable satellite data means the record has holes in it — "fragmentary."',ru:"Непоследовательный сбор плюс поздняя надёжная спутниковая съёмка означают, что в данных есть дыры, — «fragmentary»."}},{id:"rw-wic-05",skill:"Craft and Structure",topic:"Words in Context",difficulty:"hard",context:"The composer's late quartets resist the label of experiment. An experiment implies a hypothesis one may abandon; these works instead show a technique being _____, each piece refining a solution the previous one had only sketched.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["consolidated","questioned","abandoned","concealed"],answer:{kind:"choice",correct:0},explain:{en:'Each piece refines what the last one sketched, so the technique is being firmed up and built on — "consolidated."',ru:"Каждая пьеса дорабатывает намеченное в предыдущей — значит, техника закрепляется и наращивается: «consolidated»."},trap:{en:'"Questioned" belongs to the idea of experiment the passage explicitly rejects.',ru:"«Questioned» относится к идее эксперимента, которую текст прямо отвергает."}},{id:"rw-tsp-01",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"medium",context:"Most accounts of the domestication of the horse place it on the Eurasian steppe around 3500 BCE, based on wear patterns on excavated teeth. A 2021 genomic study complicates this timeline. Analysing DNA from 273 ancient horses, the authors found that the lineage underlying all modern domestic horses spread only after 2200 BCE — more than a millennium later than the dental evidence suggests. The discrepancy does not overturn the earlier work so much as narrow what it can claim.",stem:"Which choice best describes the overall structure of the text?",options:["It presents a long-standing claim, introduces evidence that qualifies it, and characterises the relationship between the two.","It describes a scientific method in detail and then lists the fields that have adopted it.","It contrasts two researchers' personalities and explains why one prevailed.","It poses a question, rejects three answers, and offers a fourth."],answer:{kind:"choice",correct:0},explain:{en:'The text moves from the established dental-evidence timeline, to a genomic study that pushes the date later, to a final sentence defining how the two relate ("narrow what it can claim").',ru:"Текст идёт от устоявшейся датировки по зубам к геномному исследованию, сдвигающему дату, и заканчивается предложением о том, как они соотносятся («narrow what it can claim»)."},trap:{en:'The last sentence explicitly says the new work does *not* overturn the old, which rules out any "one prevailed" reading.',ru:"Последнее предложение прямо говорит, что новая работа не опровергает старую, — это исключает вариант «одна победила»."}},{id:"rw-tsp-02",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"hard",context:"The following is adapted from a 1908 novel. The narrator is describing her employer's library.\n\nIt was not a room for reading. The volumes stood in ranks behind glass, spines outward, uniformly bound in a calf that had never been softened by a hand. Once I saw him unlock a case, and my heart rose; he removed a book, checked something on its title page, and returned it. The lock turned again. I understood then that the collection was an argument he was making to visitors, and that the argument did not require any of us to open it.",stem:'Which choice best states the function of the underlined phrase "my heart rose" in the text as a whole?',options:["It signals the narrator's brief expectation that the books served their ordinary purpose, which the following sentences disappoint.","It establishes that the narrator has a romantic attachment to her employer.","It emphasises the physical effort required to unlock the heavy cases.","It suggests the narrator had been forbidden from entering the room before."],answer:{kind:"choice",correct:0},explain:{en:"The narrator hopes a book is about to be read; instead it is checked and reshelved, and the lock turns. The phrase sets up the deflation that delivers the paragraph's point about display over use.",ru:"Рассказчица надеется, что книгу сейчас будут читать; вместо этого её проверяют и ставят обратно, замок щёлкает. Фраза готовит разочарование, которое и доносит мысль абзаца: показное вместо использования."}},{id:"rw-tsp-03",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"easy",context:"Lithium-ion batteries lose capacity partly because lithium metal builds up in needle-like structures called dendrites on the anode. A team at Almaty's Satbayev University tested whether a thin ceramic interlayer could suppress this growth. After 400 charge cycles, cells with the interlayer retained 91 percent of their original capacity; control cells retained 74 percent.",stem:"Which choice best states the main purpose of the text?",options:["To report a test of one proposed solution to a known battery-degradation mechanism","To argue that lithium-ion batteries should be replaced by another chemistry","To explain how a ceramic interlayer is manufactured at industrial scale","To compare battery research in Kazakhstan with research conducted elsewhere"],answer:{kind:"choice",correct:0},explain:{en:"The text names a known failure mechanism (dendrites), describes a specific intervention tested against it, and reports the numbers. That is a report of a test.",ru:"Текст называет известный механизм деградации (дендриты), описывает конкретное решение, которое проверяли, и приводит цифры. Это отчёт об испытании."}},{id:"rw-tsp-04",skill:"Craft and Structure",topic:"Cross-Text Connections",difficulty:"hard",context:"Text 1: Urban planners have long treated street trees as amenity rather than infrastructure. Recent work reverses that ordering. In cities with continuous canopy, summer surface temperatures fall by up to 12°C, storm runoff drops measurably, and the resulting savings on drainage and cooling exceed planting costs within fifteen years.\n\nText 2: The cooling figures cited for urban canopy are real but highly local. A tree lowers temperature within roughly its own shadow. Aggregated across a district, the effect on ambient air temperature is closer to 1–2°C. Planning decisions justified by the larger number will disappoint the residents who were promised them.",stem:"Based on the texts, how would the author of Text 2 most likely respond to the claim about temperature in Text 1?",options:["By agreeing that the measurement is accurate but arguing that it describes a narrower effect than the claim implies","By denying that street trees produce any measurable cooling","By insisting that drainage savings are more important than temperature","By recommending that cities plant a different species of tree"],answer:{kind:"choice",correct:0},explain:{en:'Text 2 opens by calling the figures "real" — so it accepts the measurement — then restricts its scope to a tree\'s own shadow and gives a much smaller district-wide number.',ru:"Text 2 начинается со слова «real» — то есть измерение принимается, — а затем ограничивает его тенью самого дерева и даёт куда меньшую цифру по району."},trap:{en:'"Denying any measurable cooling" contradicts the first sentence of Text 2.',ru:"«Отрицает любое охлаждение» противоречит первому предложению Text 2."}},{id:"rw-cid-01",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"easy",context:"The snow leopard's tail is nearly as long as its body. Field biologists once assumed this was principally a balance aid on steep terrain, and it is: the animal uses it as a counterweight when turning at speed on scree. But thermal imaging has shown a second function. At rest, a snow leopard wraps the tail across its muzzle, and the dense fur traps warmed exhaled air, reducing the energy the animal spends heating each breath.",stem:"Which choice best states the main idea of the text?",options:["A feature long explained by one function turns out to serve a second one as well.","Thermal imaging has replaced field observation in the study of large cats.","The snow leopard's tail is longer than that of any comparable predator.","Snow leopards spend most of their energy budget on maintaining body temperature."],answer:{kind:"choice",correct:0},explain:{en:'The text confirms the balance explanation ("and it is") and then adds a thermal one ("a second function"). The main idea is the addition, not a replacement.',ru:"Текст подтверждает объяснение про баланс («and it is») и добавляет тепловое («a second function»). Главная мысль — именно дополнение, а не замена."},trap:{en:"Option B overstates: imaging revealed something new, but the text never says it replaced field observation.",ru:"Вариант B преувеличивает: съёмка показала новое, но о замене полевых наблюдений в тексте нет ни слова."}},{id:"rw-cid-02",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"medium",context:"Between 1997 and 2019, the number of languages with a documented written orthography rose sharply, largely because missionary and NGO literacy projects produced alphabets for previously unwritten languages. Linguists disagree about the consequence. Some regard any orthography as a preservation tool. Others note that an externally designed script, once adopted in schooling, tends to standardise one dialect at the expense of the others, and that the languages showing the steepest recent decline in speaker numbers are disproportionately those that acquired a script in this period.",stem:"According to the text, what do the second group of linguists observe about languages that gained a script in this period?",options:["They are over-represented among languages losing speakers most rapidly.","They are typically spoken by fewer than one thousand people.","They have all abandoned the script within a generation.","They receive more NGO funding than languages with older scripts."],answer:{kind:"choice",correct:0},explain:{en:'The final clause states exactly this: the steepest decline in speaker numbers is "disproportionately" among languages that acquired a script in this period.',ru:"Последняя часть предложения говорит ровно это: сильнее всего теряют носителей «непропорционально» те языки, что получили письменность в этот период."}},{id:"rw-cid-03",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"hard",context:"The received view of the Silk Road as a continuous highway carrying goods from Chang'an to the Mediterranean has been hard to dislodge, partly because it is a satisfying image. The evidence supports something less tidy. Very few objects travelled the whole distance; most moved in short relays between adjacent markets, changing hands and often changing form. What travelled far were not usually goods but techniques and, more consequentially, credit arrangements — the instruments that let a merchant in Samarkand accept a claim written in Kashgar.",stem:"Which choice best states the main idea of the text?",options:["The network's long-distance significance lay less in the movement of objects than in the movement of practices and financial instruments.","Goods produced in Chang'an rarely reached markets west of Samarkand.","Historians have deliberately simplified the Silk Road to make it easier to teach.","Credit arrangements were invented by merchants working between Kashgar and Samarkand."],answer:{kind:"choice",correct:0},explain:{en:"The last sentence carries the point: not goods but techniques and credit arrangements travelled far, and credit is called the more consequential of the two.",ru:"Смысл в последнем предложении: далеко шли не товары, а техники и кредитные инструменты, причём кредит назван более значимым."},trap:{en:"Option B is a detail the text implies, not the main idea, and it drops the entire second half about techniques and credit.",ru:"Вариант B — деталь, которую текст подразумевает, а не главная мысль: он теряет всю вторую половину про техники и кредит."}},{id:"rw-coe-01",skill:"Information and Ideas",topic:"Command of Evidence (Textual)",difficulty:"medium",context:"A researcher proposes that the felt-covered walls of a traditional yurt do more than insulate: because felt absorbs sound unevenly across frequencies, she argues, the interior was acoustically suited to unamplified speech and song, favouring the human voice over ambient noise.",stem:"Which finding, if true, would most directly support the researcher's hypothesis?",options:["Measurements inside reconstructed yurts show that felt absorbs low-frequency noise strongly while reflecting the mid-range frequencies of the human voice.","Felt used in yurt construction is typically between three and five centimetres thick.","Historical accounts describe evening gatherings in yurts at which songs were performed.","Modern concert halls sometimes use wool panels to control reverberation."],answer:{kind:"choice",correct:0},explain:{en:"The hypothesis is specifically about uneven absorption across frequencies favouring the voice. Only option A measures that exact asymmetry.",ru:"Гипотеза именно о неравномерном поглощении по частотам в пользу голоса. Только вариант A измеряет эту асимметрию."},trap:{en:"Option C shows singing happened, but not that the felt caused the acoustic advantage — people sing in all sorts of rooms.",ru:"Вариант C показывает, что пели, но не то, что акустическое преимущество создавал войлок, — поют в любых помещениях."}},{id:"rw-coe-02",skill:"Information and Ideas",topic:"Command of Evidence (Quantitative)",difficulty:"hard",context:"A team surveyed four districts to see whether households that received a subsidised insulation retrofit reduced winter heating fuel use. Reported reductions in fuel purchased, one year after the retrofit:\n\nDistrict A: 31% (baseline homes: 210)\nDistrict B: 29% (baseline homes: 195)\nDistrict C: 6% (baseline homes: 188)\nDistrict D: 28% (baseline homes: 203)\n\nThe team noted that District C was the only district in which the retrofit had been installed during the heating season rather than in summer.",stem:"Which choice most effectively uses data from the text to support the conclusion that installation timing affected the retrofit's benefit?",options:["District C, the only district retrofitted mid-season, showed a reduction of 6%, while the three districts retrofitted in summer each reduced fuel use by at least 28%.","District A showed the largest reduction at 31%, which is 2 percentage points more than District B.","All four districts had a baseline sample of roughly 200 homes, making the comparison fair.","District C's 6% reduction shows that insulation retrofits do not reduce heating fuel use."],answer:{kind:"choice",correct:0},explain:{en:"The conclusion is about timing, so the evidence must pair the timing difference with the outcome difference. Option A does exactly that: the one mid-season district is also the one weak result.",ru:"Вывод — про сроки установки, значит, доказательство должно связать разницу в сроках с разницей в результате. Вариант A это и делает: единственный «зимний» район — единственный слабый результат."},trap:{en:"Option D overgeneralises from one district and ignores the three that reduced use by nearly a third.",ru:"Вариант D делает вывод по одному району и игнорирует три остальных, где расход упал почти на треть."}},{id:"rw-coe-03",skill:"Information and Ideas",topic:"Inferences",difficulty:"medium",context:"Apples brought to Kazakhstan's Tien Shan foothills from commercial orchards abroad are genetically narrow: nearly all descend from a handful of cultivars selected for shelf life. The wild Malus sieversii forests on the same slopes contain far more genetic variation, including resistance traits absent from commercial stock. Those forests have shrunk by an estimated seventy percent since 1950. Breeders who need resistance genes in the coming decades will therefore _____",stem:"Which choice most logically completes the text?",options:["depend on a wild reservoir that is disappearing faster than it is being catalogued.","find that commercial cultivars already contain every trait they require.","be able to recreate the lost variation from existing orchard stock.","no longer need to consider disease resistance in their selection programmes."],answer:{kind:"choice",correct:0},explain:{en:"The text sets up three facts: commercial stock lacks the resistance traits, the wild forests hold them, and those forests are collapsing. The inference joins them.",ru:"Текст даёт три факта: у коммерческих сортов нет генов устойчивости, у диких лесов они есть, и эти леса исчезают. Вывод их соединяет."}},{id:"rw-coe-04",skill:"Information and Ideas",topic:"Inferences",difficulty:"hard",context:"In double-blind trials of a treatment, neither patients nor the clinicians assessing them know who received the active compound. The design exists because expectation measurably alters both what a patient reports and what an observer records. A recent review found that trials of surgical procedures are far less likely than drug trials to be blinded, for practical reasons: a surgeon cannot be unaware of which operation they performed. It follows that when a surgical trial and a drug trial report similar effect sizes, _____",stem:"Which choice most logically completes the text?",options:["the surgical result carries a greater risk of being inflated by expectation than the drug result does.","the two results should be treated as equally reliable evidence.","the drug trial must have been conducted with a smaller sample.","the surgical procedure is more likely to have a genuine physiological effect."],answer:{kind:"choice",correct:0},explain:{en:"Blinding exists to control expectation effects; surgical trials are less often blinded; therefore an unblinded surgical result has more room for that inflation. The comparison is about vulnerability to bias, not about which treatment works.",ru:"Ослепление нужно, чтобы контролировать эффект ожидания; в хирургии его применяют реже; значит, у хирургического результата больше пространства для такого завышения. Сравнение — об уязвимости к смещению, а не о том, что лучше работает."},trap:{en:"Option D flips the inference: less blinding is a reason for more caution, not more confidence.",ru:"Вариант D переворачивает вывод: меньше ослепления — повод для большей осторожности, а не для большей уверенности."}}],a=[{id:"rw-bnd-01",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"easy",context:"The Charyn Canyon formed over roughly twelve million years as the river cut through layers of sedimentary rock _____ the softer layers eroded faster, leaving the columns that draw visitors today.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["rock,","rock;","rock and","rock, and"],answer:{kind:"choice",correct:1},explain:{en:"Both halves are independent clauses. A semicolon joins two independent clauses; a comma alone would be a splice.",ru:"Обе части — самостоятельные предложения. Точка с запятой соединяет два независимых предложения; одна запятая дала бы comma splice."},trap:{en:'"rock, and" would also be grammatical, but it is not offered — "rock and" without the comma is, and that version needs the comma because both sides are full clauses.',ru:"«rock, and» тоже было бы верно, но такого варианта нет: есть «rock and» без запятой, а он неверен — по обе стороны полные предложения."}},{id:"rw-bnd-02",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"medium",context:"Dinara Sadykova, _____ research on cold-adapted enzymes has been cited in more than four hundred papers, began her career studying bacteria isolated from glacial meltwater.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["who's","whose","which","whom"],answer:{kind:"choice",correct:1},explain:{en:'The clause needs a possessive: the research belongs to Sadykova. "Whose" is the possessive relative pronoun.',ru:"Нужно притяжательное местоимение: исследование принадлежит Садыковой. «Whose» — притяжательное относительное местоимение."},trap:{en:'"Who\'s" is "who is" — putting it here gives "who is research has been cited", which is not a sentence.',ru:"«Who's» — это «who is»; получилось бы «who is research has been cited», а это не предложение."}},{id:"rw-bnd-03",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"hard",context:"The team's conclusion rested on three assumptions _____ that the sediment layers were undisturbed, that the dating method was accurate within fifty years, and that the site had been occupied continuously.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["assumptions:","assumptions,","assumptions;","assumptions"],answer:{kind:"choice",correct:0},explain:{en:'A colon introduces a list that spells out something already named in a complete independent clause. "Three assumptions" announces the list; the colon delivers it.',ru:"Двоеточие вводит перечисление, раскрывающее то, что уже названо в законченном предложении. «Three assumptions» анонсирует список, двоеточие его подаёт."},trap:{en:'A semicolon needs an independent clause on both sides; the list of "that" phrases is not one.',ru:"Точке с запятой нужны полные предложения с обеих сторон, а перечисление с «that» таковым не является."}},{id:"rw-bnd-04",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"medium",context:"Having spent four winters recording wolf vocalisations in the Altai _____ able to distinguish individual animals by ear alone.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:[", the biologist was","the biologist was",", and the biologist was","; the biologist was"],answer:{kind:"choice",correct:0},explain:{en:'"Having spent four winters…" is an introductory participial phrase, so it takes a comma and must be followed by the subject it describes.',ru:"«Having spent four winters…» — вводный причастный оборот: после него ставится запятая, а дальше идёт подлежащее, к которому он относится."}},{id:"rw-bnd-05",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"hard",context:"The manuscript is remarkable less for its illustrations _____ which are conventional for the period _____ than for its marginal notes, which record the prices paid for pigments.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["—  …  —",", … ,","( … ,",", … —"],answer:{kind:"choice",correct:0},explain:{en:"A parenthetical insertion must be closed with the same mark it was opened with. Dashes on both sides is the only matched pair here.",ru:"Вставная конструкция закрывается тем же знаком, каким открыта. Тире с обеих сторон — единственная согласованная пара."},trap:{en:"Mixing a comma with a dash is the classic trap: the SAT tests matching punctuation far more often than it tests which mark you prefer.",ru:"Смешать запятую и тире — классическая ловушка: SAT гораздо чаще проверяет парность знаков, чем выбор между ними."}},{id:"rw-fss-01",skill:"Standard English Conventions",topic:"Subject-Verb Agreement",difficulty:"medium",context:"The collection of letters written by soldiers stationed along the Irtysh _____ a picture of daily life that official dispatches omit entirely.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["offer","offers","have offered","are offering"],answer:{kind:"choice",correct:1},explain:{en:'The subject is "collection", which is singular. "Of letters written by soldiers stationed along the Irtysh" is a prepositional pile-up that never changes the subject.',ru:"Подлежащее — «collection», единственное число. «Of letters written by soldiers stationed along the Irtysh» — нагромождение предлогов, которое подлежащее не меняет."},trap:{en:'"Soldiers" sits right before the blank and pulls the ear toward a plural verb. Cross out everything between the subject and the verb before choosing.',ru:"«Soldiers» стоит прямо перед пропуском и тянет к множественному числу. Вычеркни всё между подлежащим и сказуемым, прежде чем выбирать."}},{id:"rw-fss-02",skill:"Standard English Conventions",topic:"Verb Tense",difficulty:"hard",context:"By the time the excavation permit expired in 2019, the team _____ four of the six mounds identified in the initial survey.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["has opened","had opened","opens","will have opened"],answer:{kind:"choice",correct:1},explain:{en:'"By the time X happened" fixes a past reference point, and the digging finished before it. Past-before-past is the past perfect: "had opened".',ru:"«By the time X happened» задаёт точку в прошлом, а раскопки завершились до неё. Прошедшее до прошедшего — это past perfect: «had opened»."}},{id:"rw-fss-03",skill:"Standard English Conventions",topic:"Pronoun Agreement",difficulty:"medium",context:"Each of the four regional archives has digitised _____ holdings at a different pace, which makes a unified catalogue difficult to assemble.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["their","its","it's","whose"],answer:{kind:"choice",correct:1},explain:{en:'"Each" is singular, so the possessive pronoun referring back to it is "its".',ru:"«Each» — единственное число, поэтому притяжательное местоимение к нему — «its»."},trap:{en:'"It\'s" always means "it is". The possessive "its" has no apostrophe.',ru:"«It's» всегда значит «it is». У притяжательного «its» апострофа нет."}},{id:"rw-fss-04",skill:"Standard English Conventions",topic:"Modifier Placement",difficulty:"hard",context:"_____ the felt panels turned out to absorb far more sound than the researchers had predicted.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["Testing the acoustics of the reconstructed yurt,","After testing the acoustics of the reconstructed yurt,","Having tested the acoustics of the reconstructed yurt,","To test the acoustics of the reconstructed yurt,"],answer:{kind:"choice",correct:1},explain:{en:'The subject of the main clause is "the felt panels", and panels cannot test anything. Only option B avoids a dangling modifier, because "After…" does not require the subject to be the one testing.',ru:"Подлежащее главной части — «the felt panels», а панели ничего тестировать не могут. Только вариант B избегает висячего оборота: «After…» не требует, чтобы подлежащее было исполнителем."},trap:{en:"Options A, C and D are all participial or infinitive phrases whose implied doer must be the subject — which would say the panels tested themselves.",ru:"Варианты A, C и D — обороты, чей подразумеваемый деятель обязан быть подлежащим; вышло бы, что панели тестировали сами себя."}},{id:"rw-fss-05",skill:"Standard English Conventions",topic:"Parallel Structure",difficulty:"medium",context:"A good field notebook records what was observed, when the observation was made, and _____",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["the conditions under which it occurred.","under what conditions did it occur.","occurring under which conditions.","what were the conditions of its occurrence?"],answer:{kind:"choice",correct:0},explain:{en:'The list runs "what was observed" / "when the observation was made" / third item. The first two are noun clauses in statement order, and only option A continues that pattern.',ru:"Перечисление: «what was observed» / «when the observation was made» / третий элемент. Первые два — придаточные в порядке утверждения, и только вариант A продолжает эту схему."},trap:{en:'Option B slips into question word order ("did it occur"), which breaks the parallel even though it sounds natural aloud.',ru:"Вариант B соскальзывает в вопросительный порядок слов («did it occur») и ломает параллелизм, хотя на слух звучит естественно."}},{id:"rw-fss-06",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"easy",context:"The bridge was designed to carry freight _____ however, within a decade it was serving mainly passenger traffic.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["traffic,","traffic;","traffic","traffic and"],answer:{kind:"choice",correct:1},explain:{en:'"However" is a conjunctive adverb, not a conjunction: it cannot join two independent clauses with only a comma. Semicolon before, comma after.',ru:"«However» — вводное наречие, а не союз: соединить два независимых предложения одной запятой оно не может. Перед ним точка с запятой, после — запятая."}},{id:"rw-trn-01",skill:"Expression of Ideas",topic:"Transitions",difficulty:"medium",context:"Solar capacity in the region grew by 340 percent between 2018 and 2024. _____ grid upgrades did not keep pace, and by 2024 operators were curtailing output on sunny afternoons because the network could not absorb it.",stem:"Which choice completes the text with the most logical transition?",options:["For example,","Similarly,","However,","Therefore,"],answer:{kind:"choice",correct:2},explain:{en:"Rapid growth is good news; failing grid upgrades that force curtailment is the opposite. The relationship is contrast.",ru:"Быстрый рост — хорошая новость; отставание сетей, из-за которого выработку приходится ограничивать, — обратное. Связь здесь противительная."},trap:{en:'"Therefore" claims the second fact follows from the first, but growing solar capacity does not cause grids to stall — that is a separate failure.',ru:"«Therefore» утверждает, что второе следует из первого, но рост солнечной генерации не вызывает отставания сетей — это отдельная проблема."}},{id:"rw-trn-02",skill:"Expression of Ideas",topic:"Transitions",difficulty:"hard",context:"The author never claims that the ritual was widespread. She describes a single community over two decades and is careful to mark the boundaries of her sample. _____ readers have repeatedly cited the book as evidence of a region-wide practice.",stem:"Which choice completes the text with the most logical transition?",options:["Consequently,","Nonetheless,","In other words,","For instance,"],answer:{kind:"choice",correct:1},explain:{en:'The author limited her claim; readers ignored the limit anyway. "Nonetheless" marks something happening in spite of what came before.',ru:"Автор ограничила свой тезис; читатели всё равно это проигнорировали. «Nonetheless» отмечает то, что происходит вопреки сказанному."},trap:{en:'"Consequently" would mean her carefulness caused the misreading, which reverses the logic.',ru:"«Consequently» означало бы, что её аккуратность вызвала неверное прочтение, — это переворачивает логику."}},{id:"rw-trn-03",skill:"Expression of Ideas",topic:"Transitions",difficulty:"easy",context:"Permafrost holds an estimated 1,500 billion tonnes of carbon, roughly twice the amount currently in the atmosphere. _____ even a partial thaw would represent a substantial addition to the global carbon budget.",stem:"Which choice completes the text with the most logical transition?",options:["Nevertheless,","By contrast,","Consequently,","Meanwhile,"],answer:{kind:"choice",correct:2},explain:{en:'The size of the store is the reason a partial thaw matters. Cause to conclusion takes "consequently".',ru:"Объём запаса — причина того, что даже частичное таяние важно. От причины к следствию — «consequently»."}},{id:"rw-syn-01",skill:"Expression of Ideas",topic:"Rhetorical Synthesis",difficulty:"medium",context:"While researching a presentation, a student has taken the following notes:\n\n• Kazakhstan's Turkestan region receives under 250 mm of rainfall a year.\n• Cotton has been the region's dominant irrigated crop since the 1960s.\n• Cotton requires roughly 7,000 m³ of water per hectare per season.\n• Safflower yields less revenue per hectare but needs about 2,500 m³.\n• A 2023 pilot converted 400 hectares from cotton to safflower.",stem:"The student wants to emphasise the difference in water demand between the two crops. Which choice most effectively uses the relevant information from the notes to accomplish this goal?",options:["Cotton, the region's dominant irrigated crop since the 1960s, requires roughly 7,000 m³ of water per hectare each season, while safflower needs about 2,500 m³.","In 2023, a pilot project converted 400 hectares of land in the Turkestan region from cotton to safflower.","The Turkestan region receives under 250 mm of rainfall a year, which is why irrigation is necessary there.","Safflower yields less revenue per hectare than cotton, although it has been grown in the region for a shorter time."],answer:{kind:"choice",correct:0},explain:{en:"The stated goal is the water-demand difference, so the answer must put both water figures side by side. Only option A does.",ru:"Заявленная цель — разница в потреблении воды, значит, в ответе должны стоять рядом обе цифры по воде. Это делает только вариант A."},trap:{en:"Option D is true and relevant to the topic but compares revenue, not water — always answer the goal in the question, not the subject of the notes.",ru:"Вариант D верен и по теме, но сравнивает доход, а не воду. Отвечай всегда на цель из вопроса, а не на тему заметок."}},{id:"rw-syn-02",skill:"Expression of Ideas",topic:"Rhetorical Synthesis",difficulty:"hard",context:"While researching a topic, a student has taken the following notes:\n\n• The dombyra is a two-stringed Kazakh lute.\n• Küy is an instrumental genre performed on the dombyra.\n• A küy is traditionally introduced by a spoken legend explaining its origin.\n• Kurmangazy Sagyrbaiuly (1823–1896) composed more than sixty küys.\n• Ethnomusicologists note that the spoken introductions are rarely recorded on modern albums.",stem:"The student wants to present the genre to an audience unfamiliar with it and highlight something modern recordings lose. Which choice most effectively uses the relevant information from the notes to accomplish this goal?",options:["Küy, an instrumental genre played on the two-stringed dombyra, is traditionally introduced by a spoken legend about its origin — an element modern albums rarely preserve.","Kurmangazy Sagyrbaiuly, who lived from 1823 to 1896, composed more than sixty küys for the dombyra.","The dombyra is a two-stringed Kazakh lute, and küy is the instrumental genre performed on it.","Ethnomusicologists have observed that spoken introductions are rarely recorded on modern albums of Kazakh music."],answer:{kind:"choice",correct:0},explain:{en:"Two goals are set: introduce the genre to newcomers *and* name what recordings lose. Option A is the only one that does both in a single sentence.",ru:"Целей две: представить жанр незнакомой аудитории и назвать, что теряют записи. Только вариант A делает оба в одном предложении."},trap:{en:"Options C and D each satisfy exactly one half of the goal. When a synthesis question names two aims, an answer that meets one of them is still wrong.",ru:"Варианты C и D закрывают ровно по половине цели. Если в вопросе две задачи, ответ, решающий одну, всё равно неверен."}}],n=[{id:"rw2-wic-01",skill:"Craft and Structure",topic:"Words in Context",difficulty:"easy",context:"The first maps of the Caspian coastline were drawn by sailors who had never seen the shore from above. Their charts are _____ in places — a bay drawn too deep, a headland missed entirely — but the sequence of landmarks is reliable, because that is what a pilot actually needed.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["inaccurate","decorative","expensive","recent"],answer:{kind:"choice",correct:0},explain:{en:'The dashes give examples of errors — a bay too deep, a missing headland — so the blank must mean wrong in detail. "Inaccurate" fits, and the following clause contrasts it with what is reliable.',ru:"После тире идут примеры ошибок — слишком глубокий залив, пропущенный мыс, — значит, в пропуске слово со значением «неточный». «Inaccurate» подходит, а следующая часть противопоставляет ему то, что надёжно."}},{id:"rw2-wic-02",skill:"Craft and Structure",topic:"Words in Context",difficulty:"hard",context:"Reviewers praised the novel's restraint, but the quality they identified is better described as _____: the narrator does not withhold judgement so much as postpone it, allowing each character a full hearing before the book finally rules against them.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["indifference","deferral","confusion","sentimentality"],answer:{kind:"choice",correct:1},explain:{en:'The colon explains the word: judgement is "postponed" rather than withheld, and arrives at the end. "Deferral" names delay, which restraint does not.',ru:"Двоеточие расшифровывает слово: суждение «postponed», а не отсутствует, и в конце всё же выносится. «Deferral» — это отсрочка, чего слово restraint не передаёт."},trap:{en:'"Indifference" would mean the book never rules at all, but the sentence says it finally does.',ru:"«Indifference» означало бы, что книга вовсе не выносит суждения, но в предложении сказано, что в конце выносит."}},{id:"rw2-wic-03",skill:"Craft and Structure",topic:"Words in Context",difficulty:"medium",context:"Because the alloy expands and contracts far less than steel across the same temperature range, engineers describe it as dimensionally _____ — a property that makes it valuable in instruments that must hold their calibration outdoors.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["fragile","stable","porous","transparent"],answer:{kind:"choice",correct:1},explain:{en:'Little expansion or contraction means the dimensions hold steady, and holding calibration confirms it. "Stable" is the word.',ru:"Малое расширение и сжатие означают, что размеры держатся, а сохранение калибровки это подтверждает. Нужное слово — «stable»."}},{id:"rw2-wic-04",skill:"Craft and Structure",topic:"Words in Context",difficulty:"hard",context:"The committee's report is careful never to assign blame, and its authors present this as impartiality. A less charitable reading is available: an account that identifies no one as responsible is not neutral but _____, since the decisions it describes were made by people who can be named.",stem:"Which choice completes the text with the most logical and precise word or phrase?",options:["evasive","meticulous","premature","redundant"],answer:{kind:"choice",correct:0},explain:{en:'The sentence rejects "neutral" and needs a word for avoiding something that could have been stated. "Evasive" carries exactly that.',ru:"Предложение отвергает «neutral» и требует слова со значением «уклоняющийся от того, что можно было назвать». «Evasive» именно это и значит."}},{id:"rw2-tsp-01",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"medium",context:"The following is adapted from an 1889 short story. A young clerk has just been promoted.\n\nHe walked home the long way, past the shops he had priced things in for two years. The coat in the third window had not moved. He stopped, as he always stopped, and did the arithmetic — and found, with a shock that was not quite pleasure, that the arithmetic was no longer necessary. He could simply go in. He did not go in. He stood a while longer, then walked on, and could not afterwards explain to himself why.",stem:"Which choice best describes the function of the last sentence in the text?",options:["It shows the character unsettled by a change he had wanted, without resolving the feeling.","It reveals that the character has been dishonest about his promotion.","It establishes that the coat was never actually for sale.","It suggests the character intends to return to the shop the following day."],answer:{kind:"choice",correct:0},explain:{en:'The shock "was not quite pleasure", he does not buy the coat, and he cannot explain why. The sentence leaves the reaction unexplained on purpose.',ru:"Потрясение «was not quite pleasure», пальто он не покупает и не может объяснить почему. Последнее предложение намеренно оставляет реакцию без объяснения."}},{id:"rw2-tsp-02",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"hard",context:"Conventional accounts treat the printing press as the cause of the rise in literacy that followed it. The sequence is not in doubt, but the causal direction deserves scrutiny. Printing was capital-intensive, and a press could only be sustained where a paying readership already existed. In the German cities where presses multiplied fastest, school records show rising enrolment for two decades before the first press arrived. Printing did not create those readers; it found them, and then made it far cheaper to serve more of them.",stem:"Which choice best states the main purpose of the text?",options:["To qualify a widely held causal claim without denying the events it describes","To argue that the printing press had no effect on literacy rates","To describe the technical process by which early presses were built","To compare literacy in German cities with literacy elsewhere in Europe"],answer:{kind:"choice",correct:0},explain:{en:'The text accepts the sequence ("not in doubt") but reverses part of the causation, and the final sentence still grants the press a real amplifying role.',ru:"Текст принимает последовательность событий («not in doubt»), но переворачивает часть причинности, а в последнем предложении всё же признаёт за печатью усиливающую роль."},trap:{en:'Option B goes too far: "made it far cheaper to serve more of them" is an effect on literacy, just not the one usually claimed.',ru:"Вариант B заходит слишком далеко: «made it far cheaper to serve more of them» — это и есть влияние на грамотность, просто не то, о котором обычно говорят."}},{id:"rw2-tsp-03",skill:"Craft and Structure",topic:"Cross-Text Connections",difficulty:"hard",context:"Text 1: Requiring university applicants to submit a standardised test score is often defended as a fairness measure. Where school grading standards vary widely between regions, a common test is the only instrument that compares candidates on the same scale, and removing it tends to advantage applicants from schools whose reputations already speak for them.\n\nText 2: The fairness argument for standardised testing assumes the test itself is equally accessible. In practice, preparation is a purchased good: applicants who can afford tutoring gain measurable points. The test does compare candidates on one scale, but the scale registers family income alongside ability, and no amount of standardisation separates the two.",stem:"Based on the texts, the author of Text 2 would most likely characterise the argument in Text 1 as",options:["valid about grade variation but blind to an inequality inside the test itself.","entirely mistaken about the existence of regional grading differences.","correct, since standardisation removes every source of advantage.","irrelevant, because university admission should not be competitive."],answer:{kind:"choice",correct:0},explain:{en:'Text 2 concedes that the test "does compare candidates on one scale" — accepting Text 1\'s mechanism — then argues the scale also measures income, an inequality Text 1 never addresses.',ru:"Text 2 признаёт, что тест «does compare candidates on one scale», принимая механизм из Text 1, а затем утверждает, что шкала измеряет и доход — неравенство, о котором Text 1 не говорит."}},{id:"rw2-cid-01",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"medium",context:"Saiga antelope populations have collapsed and recovered repeatedly. The 2015 die-off, which killed over 200,000 animals in three weeks, was traced to a bacterium the saiga normally carry harmlessly in their tonsils. What turned a commensal organism lethal appears to have been unusually high humidity combined with warm temperatures during the calving aggregation, when the animals are packed together at their most vulnerable. The bacterium was not new; the weather that made it dangerous was.",stem:"Which choice best states the main idea of the text?",options:["An ordinarily harmless organism became lethal under specific environmental conditions.","A previously unknown bacterium was introduced into the saiga population in 2015.","Saiga antelope are more vulnerable to disease than other grazing species.","Calving aggregations should be prevented to protect the species."],answer:{kind:"choice",correct:0},explain:{en:"The last sentence states it outright: the bacterium was not new, the weather that made it dangerous was.",ru:"Последнее предложение говорит прямо: бактерия не была новой — новой была погода, сделавшая её опасной."},trap:{en:'Option B contradicts "The bacterium was not new" and "normally carry harmlessly."',ru:"Вариант B противоречит фразам «The bacterium was not new» и «normally carry harmlessly»."}},{id:"rw2-cid-02",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"hard",context:"Museums increasingly publish the provenance of contested objects — the chain of ownership from excavation to display. Advocates present this as a step towards restitution. Critics respond that documentation and return are different actions, and that publishing a chain which ends in an acquisition made under occupation can function as a substitute for acting on it: the institution demonstrates candour while the object stays exactly where it is.",stem:"According to the text, what concern do critics raise about publishing provenance?",options:["Transparency can take the place of the return it appears to promise.","The records published are usually falsified by museums.","Visitors are not interested in the history of ownership.","Provenance research is too expensive for most institutions."],answer:{kind:"choice",correct:0},explain:{en:'The critics\' point is that publishing "can function as a substitute for acting on it" — candour is demonstrated while the object does not move.',ru:"Критики говорят, что публикация «can function as a substitute for acting on it»: институция демонстрирует откровенность, а предмет остаётся на месте."}},{id:"rw2-coe-01",skill:"Information and Ideas",topic:"Command of Evidence (Textual)",difficulty:"medium",context:"A linguist argues that the rapid spread of a new slang term through a school is driven not by how many students use it but by how many distinct social groups use it: a word confined to one large clique stalls, while a word adopted by three small ones spreads.",stem:"Which finding, if true, would most directly support the linguist's argument?",options:["Terms used by four separate friendship groups spread school-wide more often than terms used by a single group twice that size.","Slang terms are typically adopted by students in their second year of secondary school.","Students report learning most new words from social media rather than from classmates.","The average slang term remains in use for about eleven months."],answer:{kind:"choice",correct:0},explain:{en:"The claim contrasts number of groups against number of users. Option A holds total users roughly constant and varies the number of groups, which is exactly the comparison being made.",ru:"Тезис противопоставляет число групп числу пользователей. Вариант A держит общее число примерно постоянным и меняет количество групп — это и есть нужное сравнение."}},{id:"rw2-coe-02",skill:"Information and Ideas",topic:"Command of Evidence (Quantitative)",difficulty:"hard",context:"A school introduced a fifteen-minute silent reading period at the start of each day and measured reading comprehension at the end of the year.\n\nGroup A (kept the period all year): +11 percentile points\nGroup B (period dropped after October): +3 percentile points\nGroup C (no period, matched intake): +2 percentile points\nGroup D (period all year, but during the final lesson): +10 percentile points",stem:"Which choice most effectively uses data from the text to support the conclusion that the duration of the programme mattered more than the time of day at which it ran?",options:["Groups A and D, which kept the period all year at different times of day, gained 11 and 10 points, while Group B, which dropped it in October, gained 3.","Group A gained 11 percentile points, which is more than any other group in the study.","Group C, which had no reading period, gained only 2 percentile points over the year.","Groups B and C gained 3 and 2 points respectively, which are very similar figures."],answer:{kind:"choice",correct:0},explain:{en:"The conclusion compares duration against timing, so the evidence must vary both. A and D differ in time of day but match on outcome; B differs in duration and collapses to near the control.",ru:"Вывод сравнивает длительность и время суток, значит, в доказательстве должны меняться оба. A и D различаются временем, но дают почти одинаковый результат; B отличается длительностью и падает почти до контрольной группы."},trap:{en:"Option B cites the largest gain but says nothing about timing, so it cannot support a claim comparing the two factors.",ru:"Вариант B приводит наибольший прирост, но ничего не говорит о времени суток, поэтому не может подтверждать сравнение двух факторов."}},{id:"rw2-coe-03",skill:"Information and Ideas",topic:"Inferences",difficulty:"medium",context:"Concrete gains most of its strength in the first month after pouring, but continues to harden for years as unreacted cement grains slowly hydrate. Cores taken from structures built in the 1930s often test stronger than the specifications those structures were designed to. Engineers assessing an old building's capacity therefore cannot rely on the design figure alone; the material may have _____",stem:"Which choice most logically completes the text?",options:["exceeded the strength it was originally required to reach.","lost all of the strength recorded at the time of construction.","been replaced at some point without documentation.","reacted with the surrounding soil in unpredictable ways."],answer:{kind:"choice",correct:0},explain:{en:"Continued hardening plus cores testing above specification leads directly to the conclusion that the material may now be stronger than the design figure.",ru:"Продолжающееся твердение плюс керны, показывающие выше проектных значений, ведут прямо к выводу: материал может быть прочнее проектной цифры."}},{id:"rw2-coe-04",skill:"Information and Ideas",topic:"Inferences",difficulty:"hard",context:"A common test of animal self-recognition places a mark on an animal where it can be seen only in a mirror. Species that touch the mark on their own body are counted as recognising themselves. The test assumes the animal is motivated to investigate an unexpected mark, and that vision is its primary means of doing so. For a species that navigates chiefly by scent and grooms by touch, a negative result therefore _____",stem:"Which choice most logically completes the text?",options:["may reflect the design of the test rather than the absence of self-recognition.","confirms that the species lacks any form of self-awareness.","shows that the animal cannot perceive the mirror at all.","indicates that the mark was placed in the wrong position."],answer:{kind:"choice",correct:0},explain:{en:"The passage names two assumptions the test rests on, then describes a species that violates both. A failure under those conditions is uninformative about the underlying ability.",ru:"Текст называет два допущения, на которых держится тест, а затем описывает вид, который обоим не отвечает. Провал в таких условиях ничего не говорит о самой способности."},trap:{en:"Option B is the conclusion the passage is warning against — it treats a failed test as a settled finding.",ru:"Вариант B — тот самый вывод, от которого текст предостерегает: провал теста принимается за установленный факт."}},{id:"rw2-cid-03",skill:"Information and Ideas",topic:"Central Ideas and Details",difficulty:"easy",context:"The Turkic runic inscriptions of the Orkhon valley, carved in the eighth century, are the earliest known written records of a Turkic language. They are unusual among monumental inscriptions in that long passages are written in the first person and address the reader directly, including admissions of political miscalculation that a commemorative text would ordinarily omit.",stem:"Which choice best states the main idea of the text?",options:["An early set of inscriptions is notable both for its date and for its unusually personal voice.","The Orkhon inscriptions were carved by several different authors over many centuries.","Monumental inscriptions from this period are rarely readable today.","Turkic languages were not written down until the modern era."],answer:{kind:"choice",correct:0},explain:{en:"The text gives two claims: earliest known Turkic records, and unusual first-person voice including admissions of error. Option A captures both.",ru:"В тексте два утверждения: древнейшие известные записи на тюркском и необычный голос от первого лица с признанием ошибок. Вариант A охватывает оба."}},{id:"rw2-tsp-04",skill:"Craft and Structure",topic:"Text Structure and Purpose",difficulty:"medium",context:"Researchers wanting to know how far a bird travels have traditionally attached a tag and waited for it to be found again — a method that yields one data point per recovered bird and nothing at all for the rest. Lightweight geolocators changed the arithmetic. Weighing under a gram, they log ambient light, from which position can be reconstructed to within about 150 kilometres. The precision is poor by satellite standards. For a species whose route across a continent was previously unknown, it is transformative.",stem:"Which choice best describes the function of the last sentence?",options:["It reframes a stated limitation as unimportant for the question being asked.","It introduces a new technology that supersedes geolocators.","It concedes that the method has failed for most species.","It explains how satellite tracking systems calculate position."],answer:{kind:"choice",correct:0},explain:{en:"The previous sentence admits the precision is poor; the final one says that for a previously unknown route it is transformative. The limitation is placed against the purpose.",ru:"Предыдущее предложение признаёт слабую точность, а последнее говорит, что для ранее неизвестного маршрута она меняет всё. Ограничение соотнесено с задачей."}}],s=[{id:"rw2-bnd-01",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"easy",context:"The mural was painted over in 1974 _____ a photograph taken the previous summer is the only record of it that survives.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["1974,","1974;","1974 and","1974 which"],answer:{kind:"choice",correct:1},explain:{en:"Two independent clauses need a semicolon, a period, or a comma plus a coordinating conjunction. Only the semicolon is offered in a correct form.",ru:"Два самостоятельных предложения соединяются точкой с запятой, точкой либо запятой с сочинительным союзом. В верной форме предложена только точка с запятой."}},{id:"rw2-bnd-02",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"hard",context:"The excavation produced three artefacts of unusual interest _____ a bronze mirror, a set of bone dice, and a wooden comb still bearing traces of pigment.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["interest:","interest;","interest,","interest, and"],answer:{kind:"choice",correct:0},explain:{en:"The clause before the blank is complete and announces a list; a colon introduces the items that spell it out.",ru:"Часть перед пропуском — законченное предложение, анонсирующее перечисление; двоеточие вводит сами элементы."},trap:{en:"A semicolon demands a full clause after it, and a bare list of noun phrases is not one.",ru:"После точки с запятой должно идти полное предложение, а перечисление именных групп таковым не является."}},{id:"rw2-bnd-03",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"medium",context:"Sholpan Zhandarbekova, _____ was among the first women to direct at the Auezov Theatre, trained as an actor before moving behind the scenes.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["who","whom","which","she"],answer:{kind:"choice",correct:0},explain:{en:'The pronoun is the subject of "was among the first", so the subject form "who" is required. "Which" cannot refer to a person.',ru:"Местоимение — подлежащее при «was among the first», значит, нужна форма подлежащего «who». «Which» к человеку не относится."},trap:{en:'Choosing "she" creates two subjects for one verb and turns the sentence into a run-on.',ru:"Вариант «she» даёт два подлежащих при одном сказуемом и превращает фразу в слитное предложение."}},{id:"rw2-bnd-04",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"medium",context:"The lake freezes each December _____ by late March the ice has broken up completely.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["December, but","December but","December,","December —"],answer:{kind:"choice",correct:0},explain:{en:'Two independent clauses joined by the coordinating conjunction "but" take a comma before it.',ru:"Два самостоятельных предложения, соединённые сочинительным союзом «but», требуют запятой перед ним."}},{id:"rw2-bnd-05",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"hard",context:"Two of the manuscripts _____ the ones catalogued in 1908 _____ have never been photographed.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:[", … ,","— … ,",", … —","( … —"],answer:{kind:"choice",correct:0},explain:{en:"A parenthetical must open and close with the same mark. Commas on both sides is the only matched pair offered.",ru:"Вставная конструкция открывается и закрывается одним и тем же знаком. Запятые с обеих сторон — единственная согласованная пара из предложенных."}},{id:"rw2-fss-01",skill:"Standard English Conventions",topic:"Subject-Verb Agreement",difficulty:"medium",context:"A series of measurements taken at stations along the river _____ that the peak flow now arrives nearly three weeks earlier than it did in 1980.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["show","shows","have shown","were showing"],answer:{kind:"choice",correct:1},explain:{en:'The subject is "a series", which is singular. Everything from "of measurements" to "river" is modification.',ru:"Подлежащее — «a series», единственное число. Всё от «of measurements» до «river» — определения."},trap:{en:'"Stations" and "measurements" are both plural and both sit closer to the verb than the actual subject does.',ru:"«Stations» и «measurements» стоят во множественном числе и ближе к сказуемому, чем настоящее подлежащее."}},{id:"rw2-fss-02",skill:"Standard English Conventions",topic:"Verb Tense",difficulty:"hard",context:"Researchers have been monitoring the colony since 2011, and by the time the current survey concludes next spring they _____ data for a full fifteen breeding seasons.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["collected","have collected","will have collected","had collected"],answer:{kind:"choice",correct:2},explain:{en:'"By the time X concludes next spring" sets a point in the future, and the collecting will be complete before it. That is the future perfect.',ru:"«By the time X concludes next spring» задаёт точку в будущем, а сбор данных завершится до неё. Это future perfect."}},{id:"rw2-fss-03",skill:"Standard English Conventions",topic:"Pronoun Agreement",difficulty:"medium",context:"Neither of the two proposals submitted to the council addressed _____ effect on traffic in the surrounding streets.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["their","its","it's","there"],answer:{kind:"choice",correct:1},explain:{en:'"Neither" is singular, so the possessive is "its".',ru:"«Neither» — единственное число, поэтому притяжательное местоимение — «its»."},trap:{en:'"Proposals" is plural and sits between the subject and the pronoun, which is exactly why the trap works.',ru:"«Proposals» стоит во множественном числе между подлежащим и местоимением — на этом ловушка и построена."}},{id:"rw2-fss-04",skill:"Standard English Conventions",topic:"Modifier Placement",difficulty:"hard",context:"_____ the report was rewritten twice before the committee accepted it.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["Although the findings were never disputed,","Disputing none of the findings,","Having disputed none of the findings,","To dispute none of the findings,"],answer:{kind:"choice",correct:0},explain:{en:'The subject of the main clause is "the report", and a report cannot dispute anything. Only the full subordinate clause in option A avoids attaching the action to it.',ru:"Подлежащее главной части — «the report», а отчёт ничего оспаривать не может. Только полное придаточное в варианте A не привязывает действие к нему."}},{id:"rw2-fss-05",skill:"Standard English Conventions",topic:"Parallel Structure",difficulty:"medium",context:"The training covers reading a topographic map, estimating distance by pacing, and _____",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["improvising a shelter from available materials.","how a shelter can be improvised from available materials.","to improvise a shelter from available materials.","a shelter improvised from available materials."],answer:{kind:"choice",correct:0},explain:{en:'The list runs "reading… / estimating… / third item". The first two are -ing phrases, so the third must be one too.',ru:"Перечисление идёт «reading… / estimating… / третий элемент». Первые два — обороты с -ing, значит, и третий должен быть таким же."}},{id:"rw2-fss-06",skill:"Standard English Conventions",topic:"Boundaries",difficulty:"medium",context:"The instrument was calibrated at the factory _____ therefore, any drift observed in the field points to a fault in the mounting rather than in the sensor.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["factory,","factory;","factory","factory and"],answer:{kind:"choice",correct:1},explain:{en:'"Therefore" is a conjunctive adverb and cannot join two independent clauses with a comma alone. Semicolon before, comma after.',ru:"«Therefore» — вводное наречие, соединить два самостоятельных предложения одной запятой оно не может. Перед ним точка с запятой, после — запятая."}},{id:"rw2-fss-07",skill:"Standard English Conventions",topic:"Possessives",difficulty:"hard",context:"Both of the museums _____ collections were merged in 1996 had been founded by the same family.",stem:"Which choice completes the text so that it conforms to the conventions of Standard English?",options:["who's","whose","which","that their"],answer:{kind:"choice",correct:1},explain:{en:'The collections belong to the museums, so a possessive relative pronoun is needed: "whose", which works for things as well as people.',ru:"Коллекции принадлежат музеям, значит, нужно притяжательное относительное местоимение «whose» — оно годится и для предметов, и для людей."}},{id:"rw2-trn-01",skill:"Expression of Ideas",topic:"Transitions",difficulty:"medium",context:"Early prototypes of the device failed within a few hundred cycles because the seal hardened and cracked. _____ the current version uses a compound that stays flexible across the full operating temperature range.",stem:"Which choice completes the text with the most logical transition?",options:["Similarly,","In response,","Nevertheless,","For example,"],answer:{kind:"choice",correct:1},explain:{en:'The second sentence describes a fix for the problem named in the first. "In response" marks a deliberate answer to it.',ru:"Второе предложение описывает решение проблемы из первого. «In response» отмечает намеренный ответ на неё."},trap:{en:'"Nevertheless" would mean the new version succeeded despite using a better compound, which reverses the logic.',ru:"«Nevertheless» означало бы, что новая версия удалась вопреки лучшему составу, — это переворачивает логику."}},{id:"rw2-trn-02",skill:"Expression of Ideas",topic:"Transitions",difficulty:"hard",context:"The survey found that most respondents could name the policy and describe its main provision accurately. _____ fewer than one in five could say which body was responsible for enforcing it.",stem:"Which choice completes the text with the most logical transition?",options:["Consequently,","Likewise,","However,","In particular,"],answer:{kind:"choice",correct:2},explain:{en:"Widespread accurate knowledge is set against a sharp gap in a related area. That is contrast.",ru:"Широкой осведомлённости противопоставлен резкий провал в смежном вопросе. Это противопоставление."}},{id:"rw2-trn-03",skill:"Expression of Ideas",topic:"Transitions",difficulty:"easy",context:"Snow cover reflects most of the sunlight that reaches it, while bare ground absorbs most of it. _____ an early thaw warms the surface faster than the air temperature alone would suggest.",stem:"Which choice completes the text with the most logical transition?",options:["By contrast,","As a result,","Even so,","Meanwhile,"],answer:{kind:"choice",correct:1},explain:{en:'The reflective difference is the cause; the faster warming is the effect. Cause to effect takes "as a result".',ru:"Разница в отражении — причина, более быстрый прогрев — следствие. От причины к следствию — «as a result»."}},{id:"rw2-syn-01",skill:"Expression of Ideas",topic:"Rhetorical Synthesis",difficulty:"medium",context:"While researching a topic, a student has taken the following notes:\n\n• The Kolsai Lakes lie in the Northern Tian Shan at 1,800 to 2,850 metres.\n• The upper lake is reachable only on foot or horseback.\n• Visitor numbers rose from 40,000 in 2015 to 210,000 in 2023.\n• A permit system was introduced in 2021, capping daily entries.\n• Water clarity readings declined between 2016 and 2020.",stem:"The student wants to emphasise the scale of the increase in visitors. Which choice most effectively uses the relevant information from the notes to accomplish this goal?",options:["Visitor numbers at the Kolsai Lakes rose from 40,000 in 2015 to 210,000 in 2023, more than a fivefold increase.","The Kolsai Lakes lie in the Northern Tian Shan, at elevations between 1,800 and 2,850 metres.","A permit system capping daily entries was introduced at the Kolsai Lakes in 2021.","Water clarity readings at the Kolsai Lakes declined between 2016 and 2020."],answer:{kind:"choice",correct:0},explain:{en:"The goal is the scale of the increase, so the answer needs both endpoints and ideally the ratio. Only option A supplies them.",ru:"Цель — масштаб роста, значит, нужны обе крайние точки и, желательно, отношение. Их даёт только вариант A."}},{id:"rw2-syn-02",skill:"Expression of Ideas",topic:"Rhetorical Synthesis",difficulty:"hard",context:"While researching a topic, a student has taken the following notes:\n\n• Felt is made by matting wool fibres together rather than weaving them.\n• Matting occurs because wool fibres have microscopic scales that interlock under pressure.\n• Felt has been produced across Central Asia for at least two thousand years.\n• Unlike woven cloth, felt does not unravel when cut.\n• Modern industrial felt is often made from synthetic fibres that lack scales, and requires adhesives.",stem:"The student wants to explain what makes traditional felt different from woven cloth and why the difference arises. Which choice most effectively uses the relevant information from the notes to accomplish this goal?",options:["Felt is matted rather than woven — its fibres interlock through microscopic scales — which is why, unlike woven cloth, it does not unravel when cut.","Felt has been produced across Central Asia for at least two thousand years, far longer than most woven textiles.","Modern industrial felt is often made from synthetic fibres, which lack scales and therefore require adhesives.","Wool fibres have microscopic scales that interlock with one another when pressure is applied to them."],answer:{kind:"choice",correct:0},explain:{en:"Two goals: name the difference from woven cloth and explain its cause. Option A gives the mechanism (scales interlocking) and the consequence (does not unravel) in one sentence.",ru:"Целей две: назвать отличие от тканого полотна и объяснить причину. Вариант A даёт и механизм (сцепление чешуек), и следствие (не осыпается) в одном предложении."},trap:{en:"Option D states the mechanism but never mentions woven cloth, so it answers only half the goal.",ru:"Вариант D называет механизм, но не упоминает тканое полотно, то есть отвечает лишь на половину задачи."}}],o=[{id:"m-alg-01",skill:"Algebra",topic:"Linear models",difficulty:"easy",stem:"A translator charges 4,500 tenge for the first page of a document and 1,800 tenge for each page after the first. Which function gives the total charge C, in tenge, for a document of p pages, where p ≥ 1?",options:["C(p) = 1,800p + 4,500","C(p) = 1,800p + 2,700","C(p) = 4,500p + 1,800","C(p) = 6,300p"],answer:{kind:"choice",correct:1},explain:{en:"Only p − 1 pages are billed at 1,800: C = 4,500 + 1,800(p − 1) = 1,800p + 2,700. Check p = 1: C = 4,500. ✓",ru:"По 1 800 оплачиваются только p − 1 страниц: C = 4 500 + 1 800(p − 1) = 1 800p + 2 700. Проверка при p = 1: C = 4 500. ✓"},trap:{en:"Option A charges 1,800 for the first page as well, giving 6,300 for a one-page document.",ru:"Вариант A берёт 1 800 и за первую страницу — за одностраничный документ выходит 6 300."}},{id:"m-alg-02",skill:"Algebra",topic:"Systems with no solution",difficulty:"medium",stem:"3x + ky = 12\n9x + 15y = 7\n\nIn the given system of equations, k is a constant. If the system has no solution, what is the value of k?",answer:{kind:"text",accept:["5"]},explain:{en:"No solution means the lines are parallel: the x and y coefficients are proportional while the constants are not. 3/9 = k/15 gives k = 5. The constants 12 and 7 are not in that ratio, so the system is genuinely inconsistent.",ru:"Нет решений — прямые параллельны: коэффициенты при x и y пропорциональны, а свободные члены нет. 3/9 = k/15 даёт k = 5. Свободные члены 12 и 7 в это отношение не попадают, значит, система действительно несовместна."},trap:{en:'If the constants had also matched the ratio, the answer would have been "infinitely many solutions", not "none". Always check the third ratio.',ru:"Если бы и свободные члены попали в то же отношение, было бы «бесконечно много решений», а не «нет». Третье отношение проверяй всегда."}},{id:"m-alg-03",skill:"Algebra",topic:"Systems with infinitely many solutions",difficulty:"hard",stem:"ax + 6y = 18\n4x + 12y = b\n\nIn the given system of equations, a and b are constants. If the system has infinitely many solutions, what is the value of a + b?",answer:{kind:"text",accept:["38"]},explain:{en:"Infinitely many solutions means the two equations are the same line, so all three ratios match. From the y terms, 6/12 = 1/2, so a/4 = 1/2 gives a = 2 and 18/b = 1/2 gives b = 36. Therefore a + b = 38.",ru:"Бесконечно много решений — это одна и та же прямая, значит, совпадают все три отношения. По y: 6/12 = 1/2, отсюда a/4 = 1/2 → a = 2, и 18/b = 1/2 → b = 36. Итого a + b = 38."}},{id:"m-alg-04",skill:"Advanced Math",topic:"Discriminant",difficulty:"medium",stem:"kx² − 12x + 9 = 0\n\nIn the given equation, k is a nonzero constant. If the equation has exactly one real solution, what is the value of k?",answer:{kind:"text",accept:["4"]},explain:{en:"Exactly one real solution means the discriminant is zero: b² − 4ac = 144 − 36k = 0, so k = 4.",ru:"Ровно одно действительное решение — дискриминант равен нулю: b² − 4ac = 144 − 36k = 0, значит, k = 4."}},{id:"m-alg-05",skill:"Advanced Math",topic:"Discriminant",difficulty:"hard",stem:"The quadratic equation ax² + 40x + c = 0 has exactly one real solution, where a and c are constants. What is the value of ac?",answer:{kind:"text",accept:["400"]},explain:{en:"One real solution puts the discriminant at zero: 40² − 4ac = 0, so 4ac = 1,600 and ac = 400. Neither a nor c is determined alone — only their product is, which is exactly what the question asks for.",ru:"Одно решение — дискриминант ноль: 40² − 4ac = 0, отсюда 4ac = 1 600 и ac = 400. По отдельности ни a, ни c не находятся — определено только произведение, о нём и спрашивают."},trap:{en:"Students often stall looking for a and c separately. When a question asks for a product or a sum, the individual values are usually not recoverable.",ru:"Многие застревают, пытаясь найти a и c по отдельности. Если спрашивают произведение или сумму, значения по отдельности обычно и не находятся."}},{id:"m-alg-06",skill:"Advanced Math",topic:"Zeros and vertex",difficulty:"hard",stem:"(x + 5) is a factor of the quadratic function f, and x = r is the positive zero of f. The minimum of f occurs at the point (1, −18). What is the value of r?",answer:{kind:"text",accept:["7"]},explain:{en:"A parabola is symmetric about its vertex, so the vertex x-value is the midpoint of the two zeros. The zeros are −5 and r, and the vertex is at x = 1: (−5 + r)/2 = 1, so r = 7.",ru:"Парабола симметрична относительно вершины, поэтому x вершины — середина между корнями. Корни −5 и r, вершина при x = 1: (−5 + r)/2 = 1, значит, r = 7."},trap:{en:"The value −18 is not needed. Extra information is a standard hard-question device — identify what the symmetry alone gives you.",ru:"Число −18 не нужно. Лишние данные — типичный приём в сложных задачах: сначала пойми, что даёт одна только симметрия."}},{id:"m-alg-07",skill:"Advanced Math",topic:"Zeros and coefficients",difficulty:"medium",stem:"The function f is defined by f(x) = x² + bx + c, where b and c are constants. If (x + 7) is a factor of f and 3 is the other zero of f, what is the value of b + c?",options:["−17","−4","4","25"],answer:{kind:"choice",correct:0},explain:{en:"The zeros are −7 and 3, so f(x) = (x + 7)(x − 3) = x² + 4x − 21. Then b = 4 and c = −21, so b + c = −17.",ru:"Корни −7 и 3, значит, f(x) = (x + 7)(x − 3) = x² + 4x − 21. Тогда b = 4, c = −21 и b + c = −17."},trap:{en:"The factor (x + 7) corresponds to the zero x = −7, not x = 7. Sign-flipping here is the most common single error on factor questions.",ru:"Множителю (x + 7) соответствует корень x = −7, а не x = 7. Путаница со знаком — самая частая ошибка в задачах на множители."}},{id:"m-alg-08",skill:"Advanced Math",topic:"Line and parabola",difficulty:"hard",stem:"y = 2x² + 8x + c\ny = 3x + 1\n\nIn the given system, c is a constant. The graphs intersect at exactly one point in the xy-plane. What is the value of c?",answer:{kind:"text",accept:["33/8","4.125"]},explain:{en:"Set them equal: 2x² + 8x + c = 3x + 1, so 2x² + 5x + (c − 1) = 0. One intersection means the discriminant is zero: 25 − 8(c − 1) = 0, so 8c = 33 and c = 33/8.",ru:"Приравняем: 2x² + 8x + c = 3x + 1, отсюда 2x² + 5x + (c − 1) = 0. Одна точка пересечения — дискриминант ноль: 25 − 8(c − 1) = 0, значит, 8c = 33 и c = 33/8."}},{id:"m-alg-09",skill:"Advanced Math",topic:"Exponential models",difficulty:"hard",stem:"A model estimates that a petri dish initially holds 24,000 bacteria. Fourteen days later the model estimates 96,000 bacteria. Assuming the growth is exponential and follows N = 24,000 · 2^(t/k), where t is the number of days and k is a constant, what is the value of k?",answer:{kind:"text",accept:["7"]},explain:{en:"96,000 / 24,000 = 4, so 2^(14/k) = 4 = 2². The exponents must match: 14/k = 2, so k = 7. In words: the population doubles every 7 days.",ru:"96 000 / 24 000 = 4, значит, 2^(14/k) = 4 = 2². Показатели равны: 14/k = 2, отсюда k = 7. Словами: популяция удваивается каждые 7 дней."},trap:{en:"k is the doubling time, not the number of doublings. Quadrupling in 14 days is two doublings, so each takes 7 days.",ru:"k — это время удвоения, а не число удвоений. Учетверение за 14 дней — это два удвоения, значит, на каждое приходится 7 дней."}},{id:"m-alg-10",skill:"Advanced Math",topic:"Exponential models",difficulty:"medium",stem:"A machine purchased for 480,000 tenge loses 12% of its value each year. Which function gives the value V, in tenge, of the machine t years after purchase?",options:["V(t) = 480,000(0.12)^t","V(t) = 480,000(1.12)^t","V(t) = 480,000(0.88)^t","V(t) = 480,000 − 0.12t"],answer:{kind:"choice",correct:2},explain:{en:"Losing 12% leaves 88%, so each year the value is multiplied by 0.88: V(t) = 480,000(0.88)^t.",ru:"Потеря 12% оставляет 88%, поэтому каждый год стоимость умножается на 0,88: V(t) = 480 000(0,88)^t."},trap:{en:"Option D describes a constant loss of 0.12 tenge per year — linear, not percentage, decay.",ru:"Вариант D описывает постоянную потерю в 0,12 тенге в год — линейное убывание, а не процентное."}},{id:"m-alg-11",skill:"Advanced Math",topic:"Rational exponents",difficulty:"medium",stem:"If x^(3/4) = 27 and x > 0, what is the value of x?",answer:{kind:"text",accept:["81"]},explain:{en:"Raise both sides to the 4/3 power: x = 27^(4/3) = (27^(1/3))⁴ = 3⁴ = 81.",ru:"Возведём обе части в степень 4/3: x = 27^(4/3) = (27^(1/3))⁴ = 3⁴ = 81."}},{id:"m-alg-12",skill:"Advanced Math",topic:"Rational exponents",difficulty:"hard",stem:"The numbers a and b are both greater than zero, and the cube root of a is equal to the fourth root of b. For what value of n is aⁿ equal to b?",answer:{kind:"text",accept:["4/3","1.333","1.3333"]},explain:{en:"a^(1/3) = b^(1/4). Raise both sides to the 3rd power: a = b^(3/4). Then aⁿ = b^(3n/4), and setting that equal to b¹ gives 3n/4 = 1, so n = 4/3.",ru:"a^(1/3) = b^(1/4). Возведём обе части в куб: a = b^(3/4). Тогда aⁿ = b^(3n/4), приравняв к b¹, получаем 3n/4 = 1, значит, n = 4/3."},trap:{en:"Grid-ins accept 4/3; a rounded 1.33 is outside the accepted range on the real test. Enter the fraction.",ru:"В grid-in вводи 4/3: округлённое 1,33 на реальном экзамене не засчитается. Пиши дробь."}},{id:"m-alg-13",skill:"Advanced Math",topic:"Equations in quadratic form",difficulty:"hard",stem:"x⁴ − 13x² + 36 = 0\n\nWhat is the greatest solution to the given equation?",answer:{kind:"text",accept:["3"]},explain:{en:"Let u = x². Then u² − 13u + 36 = 0 factors as (u − 4)(u − 9) = 0, so x² = 4 or x² = 9. The solutions are ±2 and ±3, and the greatest is 3.",ru:"Пусть u = x². Тогда u² − 13u + 36 = 0 раскладывается как (u − 4)(u − 9) = 0, значит, x² = 4 или x² = 9. Решения ±2 и ±3, наибольшее — 3."},trap:{en:"Stopping at u = 9 and answering 9 is the designed mistake — u is x², not x.",ru:"Остановиться на u = 9 и написать 9 — это и есть заложенная ошибка: u — это x², а не x."}},{id:"m-alg-14",skill:"Algebra",topic:"Absolute value",difficulty:"medium",stem:"|2x − 7| = 11\n\nWhat is the sum of the solutions to the given equation?",answer:{kind:"text",accept:["7"]},explain:{en:"Split into 2x − 7 = 11 giving x = 9, and 2x − 7 = −11 giving x = −2. The sum is 7.",ru:"Разбиваем: 2x − 7 = 11 даёт x = 9, и 2x − 7 = −11 даёт x = −2. Сумма равна 7."},trap:{en:"Solving only the positive case and answering 9 loses the second root. An absolute-value equation almost always has two.",ru:"Решить только положительный случай и написать 9 — потерять второй корень. У уравнения с модулем почти всегда два решения."}},{id:"m-alg-15",skill:"Advanced Math",topic:"Function notation",difficulty:"easy",stem:"The functions f and g are defined by f(x) = 3x − 5 and g(x) = x² + 2. What is the value of g(f(3))?",answer:{kind:"text",accept:["18"]},explain:{en:"Work from the inside out: f(3) = 9 − 5 = 4, then g(4) = 16 + 2 = 18.",ru:"Считаем изнутри наружу: f(3) = 9 − 5 = 4, затем g(4) = 16 + 2 = 18."},trap:{en:"Computing f(g(3)) instead gives 3(11) − 5 = 28. Composition is not commutative — read which function is on the outside.",ru:"Если посчитать f(g(3)), выйдет 3·11 − 5 = 28. Композиция не коммутативна — смотри, какая функция снаружи."}},{id:"m-alg-16",skill:"Algebra",topic:"Linear functions",difficulty:"medium",stem:"The function h is linear, h(2) = 17, and h(6) = 5. What is the value of h(0)?",answer:{kind:"text",accept:["23"]},explain:{en:"The slope is (5 − 17)/(6 − 2) = −3. Going back from x = 2 to x = 0 adds 2 × 3 = 6, so h(0) = 17 + 6 = 23.",ru:"Наклон равен (5 − 17)/(6 − 2) = −3. Идя от x = 2 к x = 0, прибавляем 2 · 3 = 6, значит, h(0) = 17 + 6 = 23."}},{id:"m-alg-17",skill:"Algebra",topic:"Systems of inequalities",difficulty:"medium",stem:"y > 2x − 3\ny ≤ −x + 6\n\nWhich of the following ordered pairs (x, y) is a solution to the given system of inequalities?",options:["(4, 1)","(1, 4)","(3, 4)","(0, −4)"],answer:{kind:"choice",correct:1},explain:{en:"Test (1, 4): 4 > 2(1) − 3 = −1 ✓ and 4 ≤ −1 + 6 = 5 ✓. Both hold, so (1, 4) works.",ru:"Проверим (1, 4): 4 > 2·1 − 3 = −1 ✓ и 4 ≤ −1 + 6 = 5 ✓. Оба условия выполнены, значит, (1, 4) подходит."},trap:{en:"(3, 4) satisfies the first inequality but fails the second: 4 ≤ 3 is false. Always test both — a point that passes one is designed to look right.",ru:"(3, 4) проходит первое неравенство, но не второе: 4 ≤ 3 неверно. Проверяй оба — точка, проходящая одно, специально выглядит правдоподобно."}},{id:"m-alg-18",skill:"Algebra",topic:"Systems word problems",difficulty:"medium",stem:"A workshop sells stools for 6,000 tenge each and tables for 22,000 tenge each. Last month it sold 47 items in total for 586,000 tenge. How many tables did it sell?",answer:{kind:"text",accept:["19"]},explain:{en:"With s stools and t tables: s + t = 47 and 6,000s + 22,000t = 586,000. Substituting s = 47 − t gives 282,000 + 16,000t = 586,000, so 16,000t = 304,000 and t = 19.",ru:"Пусть s — табуреты, t — столы: s + t = 47 и 6 000s + 22 000t = 586 000. Подставив s = 47 − t, получаем 282 000 + 16 000t = 586 000, отсюда 16 000t = 304 000 и t = 19."}},{id:"m-alg-19",skill:"Algebra",topic:"Rational equations",difficulty:"medium",stem:"5/(x − 2) = 15/(x + 4)\n\nWhat value of x satisfies the given equation?",answer:{kind:"text",accept:["5"]},explain:{en:"Cross-multiply: 5(x + 4) = 15(x − 2), so 5x + 20 = 15x − 30, giving 10x = 50 and x = 5. Neither denominator is zero at x = 5, so the solution is valid.",ru:"Перемножим крест-накрест: 5(x + 4) = 15(x − 2), отсюда 5x + 20 = 15x − 30, значит, 10x = 50 и x = 5. При x = 5 ни один знаменатель не обнуляется, решение годится."},trap:{en:"Always check the answer against the excluded values (here x ≠ 2 and x ≠ −4). A rational equation can produce a root that has to be thrown away.",ru:"Всегда сверяй ответ с запрещёнными значениями (здесь x ≠ 2 и x ≠ −4). Дробное уравнение может дать корень, который придётся отбросить."}},{id:"m-alg-20",skill:"Algebra",topic:"Systems solved for an expression",difficulty:"hard",stem:"(a − b) − 16(c + d) = 300\n(a − b) + 12(c + d) = 720\n\nFor the given system of equations, what is the value of 7(a − b)?",answer:{kind:"text",accept:["3780"]},explain:{en:"Treat u = a − b and v = c + d as single unknowns. Subtracting the first equation from the second gives 28v = 420, so v = 15. Then u = 720 − 12(15) = 540, and 7u = 3,780.",ru:"Считай u = a − b и v = c + d отдельными неизвестными. Вычитая первое уравнение из второго, получаем 28v = 420, значит, v = 15. Тогда u = 720 − 12·15 = 540, и 7u = 3 780."},trap:{en:"There is no way to find a, b, c or d individually — four unknowns, two equations. Recognising that the grouped expressions *are* the unknowns is the whole problem.",ru:"Найти a, b, c, d по отдельности невозможно: четыре неизвестных, два уравнения. Вся задача — понять, что неизвестные и есть эти скобки."}},{id:"m-alg-21",skill:"Algebra",topic:"Parallel and perpendicular lines",difficulty:"medium",stem:"Line ℓ passes through the point (−4, 9) and is perpendicular to the line with equation 3x + 6y = 18. What is the y-coordinate of the y-intercept of line ℓ?",answer:{kind:"text",accept:["17"]},explain:{en:"Rewrite 3x + 6y = 18 as y = −½x + 3, so its slope is −½ and the perpendicular slope is 2. Using y = 2x + b through (−4, 9): 9 = −8 + b, so b = 17.",ru:"Перепишем 3x + 6y = 18 как y = −½x + 3, наклон равен −½, перпендикулярный — 2. Подставим (−4, 9) в y = 2x + b: 9 = −8 + b, значит, b = 17."}},{id:"m-alg-22",skill:"Advanced Math",topic:"Polynomial factors",difficulty:"medium",stem:"The polynomial p is defined by p(x) = x³ − 4x² + x + 6. Which of the following must be a factor of p?",options:["x − 1","x + 2","x − 3","x + 6"],answer:{kind:"choice",correct:2},explain:{en:"By the factor theorem, (x − k) is a factor exactly when p(k) = 0. Here p(3) = 27 − 36 + 3 + 6 = 0, so (x − 3) is a factor.",ru:"По теореме Безу (x − k) — множитель тогда и только тогда, когда p(k) = 0. Здесь p(3) = 27 − 36 + 3 + 6 = 0, значит, (x − 3) — множитель."},trap:{en:"For option B you must test p(−2), not p(2). The factor (x + 2) corresponds to the root −2.",ru:"Для варианта B нужно проверять p(−2), а не p(2): множителю (x + 2) отвечает корень −2."}},{id:"m-alg-23",skill:"Advanced Math",topic:"Quadratic minimum",difficulty:"easy",stem:"What is the minimum value of the function f defined by f(x) = x² − 10x + 34?",answer:{kind:"text",accept:["9"]},explain:{en:"The vertex sits at x = −b/(2a) = 10/2 = 5, and f(5) = 25 − 50 + 34 = 9. Completing the square shows the same thing: f(x) = (x − 5)² + 9.",ru:"Вершина при x = −b/(2a) = 10/2 = 5, и f(5) = 25 − 50 + 34 = 9. Выделение полного квадрата даёт то же: f(x) = (x − 5)² + 9."},trap:{en:"The question asks for the minimum *value* (the y-coordinate), not the x that produces it. Answering 5 is the standard slip.",ru:"Спрашивают минимальное значение (координату y), а не x, при котором оно достигается. Ответ 5 — типичная ошибка."}},{id:"m-alg-24",skill:"Algebra",topic:"Percent change",difficulty:"easy",stem:"684 is p% greater than 570. What is the value of p?",answer:{kind:"text",accept:["20"]},explain:{en:"The increase is 684 − 570 = 114, and percent change compares it with the original: 114/570 = 0.2, so p = 20.",ru:"Прирост равен 684 − 570 = 114, а процент считается от исходного значения: 114/570 = 0,2, значит, p = 20."},trap:{en:"Dividing by 684 instead of 570 gives about 16.7. The base of a percent change is always the value you started from.",ru:"Деление на 684 вместо 570 даёт около 16,7. База процентного изменения — всегда исходное значение."}}],r=[{id:"m-dat-01",skill:"Problem-Solving and Data Analysis",topic:"Unit conversion",difficulty:"hard",stem:"A certain town has an area of 5.48 square miles. Which of the following is closest to the area of this town, in square yards? (1 mile = 1,760 yards)",options:["9,645","16,974,848","552","964"],answer:{kind:"choice",correct:1},explain:{en:"Converting an area squares the conversion factor: 1 square mile = 1,760² = 3,097,600 square yards. So 5.48 × 3,097,600 = 16,974,848.",ru:"При переводе площади множитель возводится в квадрат: 1 квадратная миля = 1 760² = 3 097 600 квадратных ярдов. Значит, 5,48 × 3 097 600 = 16 974 848."},trap:{en:"Multiplying by 1,760 once gives about 9,645 — the answer that is deliberately offered. Length converts once, area twice, volume three times.",ru:"Умножение на 1 760 один раз даёт примерно 9 645 — этот вариант подсунут специально. Длина переводится один раз, площадь — два, объём — три."}},{id:"m-dat-02",skill:"Geometry and Trigonometry",topic:"Polygon angles",difficulty:"hard",stem:"A polygon has exactly 97 sides. If the measure of each of the 97 interior angles of this regular polygon is (180a)°, what is the value of a?",answer:{kind:"text",accept:["95/97",".9793","0.9794",".9794"]},explain:{en:"The interior angles of an n-sided polygon sum to (n − 2) × 180°, so each angle of a regular 97-gon is 95 × 180/97 degrees. Setting that equal to 180a gives a = 95/97.",ru:"Сумма внутренних углов n-угольника равна (n − 2) · 180°, поэтому каждый угол правильного 97-угольника равен 95 · 180/97 градусов. Приравняв к 180a, получаем a = 95/97."},trap:{en:"The 180 cancels — you never have to compute the angle itself. Grinding out 176.29° first is where the time goes.",ru:"180 сокращается — сам угол считать не нужно. Время теряется именно на вычислении 176,29°."}},{id:"m-dat-03",skill:"Geometry and Trigonometry",topic:"Circles in the xy-plane",difficulty:"hard",stem:"A circle in the xy-plane has its centre at (3, −7) and a radius of 12. An equation of this circle is x² + y² + ax + by + c = 0, where a, b and c are constants. What is the value of c?",answer:{kind:"text",accept:["-86"]},explain:{en:"Start from (x − 3)² + (y + 7)² = 144. Expanding: x² − 6x + 9 + y² + 14y + 49 = 144, so x² + y² − 6x + 14y + 58 − 144 = 0. Therefore c = −86.",ru:"Начнём с (x − 3)² + (y + 7)² = 144. Раскрываем: x² − 6x + 9 + y² + 14y + 49 = 144, значит, x² + y² − 6x + 14y + 58 − 144 = 0. Отсюда c = −86."},trap:{en:"Forgetting to subtract the 144 leaves c = 58. The radius term has to cross to the left side with the rest.",ru:"Если забыть вычесть 144, получится c = 58. Член с радиусом обязан перейти влево вместе с остальными."}},{id:"m-dat-04",skill:"Geometry and Trigonometry",topic:"Volume scaling",difficulty:"medium",stem:"Sphere A has a radius of 7r and sphere B has a radius of 91r, where r > 0. The volume of sphere B is how many times the volume of sphere A?",answer:{kind:"text",accept:["2197"]},explain:{en:"The radii are in the ratio 91/7 = 13. Volume scales with the cube of the linear ratio, so the factor is 13³ = 2,197.",ru:"Радиусы относятся как 91/7 = 13. Объём растёт как куб линейного отношения, поэтому множитель равен 13³ = 2 197."},trap:{en:"Answering 13 uses the linear ratio; answering 169 uses the area ratio. Volume needs the third power.",ru:"Ответ 13 — это линейное отношение, 169 — отношение площадей. Для объёма нужна третья степень."}},{id:"m-dat-05",skill:"Geometry and Trigonometry",topic:"Complementary angles",difficulty:"medium",stem:"For two acute angles P and Q, cos P = sin Q. The measures, in degrees, of ∠P and ∠Q are (3x + 10) and (2x + 5), respectively. What is the value of x?",answer:{kind:"text",accept:["15"]},explain:{en:"For acute angles, cos P = sin Q exactly when P and Q are complementary. So (3x + 10) + (2x + 5) = 90, giving 5x + 15 = 90 and x = 15.",ru:"Для острых углов cos P = sin Q выполняется тогда, когда P и Q дополняют друг друга до 90°. Значит, (3x + 10) + (2x + 5) = 90, отсюда 5x + 15 = 90 и x = 15."},trap:{en:"Setting the two expressions equal to each other gives x = −5 and a negative angle. The identity relates the angles' sum, not the angles themselves.",ru:"Если приравнять выражения друг к другу, получится x = −5 и отрицательный угол. Тождество связывает сумму углов, а не сами углы."}},{id:"m-dat-06",skill:"Geometry and Trigonometry",topic:"Right triangle trigonometry",difficulty:"medium",stem:"In triangle ABC, the sum of the measures of angle A and angle B is 90 degrees. If sin A = 5/13, what is the value of cos B?",answer:{kind:"text",accept:["5/13",".3846","0.3846"]},explain:{en:"Since A + B = 90°, angle B = 90° − A, and cos(90° − A) = sin A. So cos B = 5/13 directly.",ru:"Так как A + B = 90°, угол B = 90° − A, а cos(90° − A) = sin A. Значит, cos B = 5/13 сразу."},trap:{en:"There is no need to find the third side or use 12/13 anywhere. The co-function identity answers it in one step.",ru:"Третью сторону искать не нужно, и 12/13 здесь ни при чём. Тождество кофункций решает задачу за один шаг."}},{id:"m-dat-07",skill:"Geometry and Trigonometry",topic:"Triangle area",difficulty:"hard",stem:"The area of a triangle is x² square inches. The base of the triangle is (5 + 2x) inches and the height is (x − 2) inches. What is the value of x?",answer:{kind:"text",accept:["10"]},explain:{en:"Area = ½ × base × height, so ½(5 + 2x)(x − 2) = x². Multiply by 2: (5 + 2x)(x − 2) = 2x², which expands to 2x² + x − 10 = 2x². The quadratic terms cancel, leaving x = 10.",ru:"Площадь = ½ · основание · высота, значит, ½(5 + 2x)(x − 2) = x². Умножим на 2: (5 + 2x)(x − 2) = 2x², раскрываем: 2x² + x − 10 = 2x². Квадратичные члены сокращаются, остаётся x = 10."},trap:{en:"The problem looks quadratic and turns out to be linear. When both sides carry the same x² term, cancel before reaching for the quadratic formula.",ru:"Задача выглядит квадратной, а оказывается линейной. Если с обеих сторон одинаковый x², сокращай его, не хватаясь за формулу корней."}},{id:"m-dat-08",skill:"Geometry and Trigonometry",topic:"Right triangle trigonometry",difficulty:"medium",stem:"A right triangle has a hypotenuse of length 25 and one leg of length 7. What is the tangent of the angle opposite the leg of length 7?",answer:{kind:"text",accept:["7/24",".2917","0.2917"]},explain:{en:"The other leg is √(625 − 49) = √576 = 24. Tangent is opposite over adjacent, so tan = 7/24.",ru:"Второй катет равен √(625 − 49) = √576 = 24. Тангенс — противолежащий к прилежащему, значит, tan = 7/24."},trap:{en:"7/25 is the sine, not the tangent. Tangent never uses the hypotenuse.",ru:"7/25 — это синус, а не тангенс. В тангенсе гипотенуза не участвует вообще."}},{id:"m-dat-09",skill:"Geometry and Trigonometry",topic:"Circles",difficulty:"easy",stem:"A sector of a circle has a radius of 9 and a central angle measuring 80°. What is the area of this sector?",options:["18π","20π","9π","72π"],answer:{kind:"choice",correct:0},explain:{en:"The sector is 80/360 = 2/9 of the circle, and the whole circle has area π(9²) = 81π. So the sector is (2/9)(81π) = 18π.",ru:"Сектор составляет 80/360 = 2/9 круга, а площадь всего круга равна π · 9² = 81π. Значит, сектор равен (2/9) · 81π = 18π."}},{id:"m-dat-10",skill:"Geometry and Trigonometry",topic:"Inscribed angles",difficulty:"medium",stem:"In a circle, a central angle measures 74°. What is the measure, in degrees, of an inscribed angle that subtends the same arc?",answer:{kind:"text",accept:["37"]},explain:{en:"An inscribed angle is half the central angle subtending the same arc, so it measures 74/2 = 37°.",ru:"Вписанный угол вдвое меньше центрального, опирающегося на ту же дугу, значит, он равен 74/2 = 37°."},trap:{en:"The relationship runs one way only: the inscribed angle is the half. Doubling to 148° reverses it.",ru:"Соотношение работает только в одну сторону: половина — это вписанный угол. Удвоение до 148° переворачивает его."}},{id:"m-dat-11",skill:"Geometry and Trigonometry",topic:"Similar solids",difficulty:"hard",stem:"Two similar rectangular prisms have surface areas in the ratio 9 : 25. What is the ratio of their volumes?",options:["3 : 5","9 : 25","27 : 125","81 : 625"],answer:{kind:"choice",correct:2},explain:{en:"Surface area scales with the square of the linear ratio, so the linear ratio is √9 : √25 = 3 : 5. Volume scales with the cube, giving 27 : 125.",ru:"Площадь поверхности растёт как квадрат линейного отношения, поэтому линейное отношение равно √9 : √25 = 3 : 5. Объём растёт как куб, отсюда 27 : 125."},trap:{en:"You must step down to the linear ratio first and only then cube it. Cubing 9 : 25 directly gives the wrong answer.",ru:"Сначала нужно спуститься к линейному отношению и лишь затем возводить в куб. Возведение 9 : 25 в куб напрямую даёт неверный ответ."}},{id:"m-dat-12",skill:"Geometry and Trigonometry",topic:"Radians",difficulty:"easy",stem:"An angle measures 5π/6 radians. What is the measure of this angle, in degrees?",answer:{kind:"text",accept:["150"]},explain:{en:"Multiply by 180/π: (5π/6)(180/π) = 5 × 30 = 150 degrees.",ru:"Умножаем на 180/π: (5π/6) · (180/π) = 5 · 30 = 150 градусов."}},{id:"m-dat-13",skill:"Geometry and Trigonometry",topic:"Volume and rate",difficulty:"medium",stem:"Water flows into an empty cylindrical tank with a base area of 2.5 square metres at a constant rate of 0.75 cubic metres per minute. How many minutes does it take for the water to reach a depth of 3 metres?",answer:{kind:"text",accept:["10"]},explain:{en:"The volume needed is base area × depth = 2.5 × 3 = 7.5 cubic metres. At 0.75 per minute that takes 7.5/0.75 = 10 minutes.",ru:"Нужный объём равен площадь основания × глубина = 2,5 · 3 = 7,5 кубометра. При 0,75 в минуту это займёт 7,5/0,75 = 10 минут."}},{id:"m-dat-14",skill:"Problem-Solving and Data Analysis",topic:"Mean",difficulty:"easy",stem:"The mean of five numbers is 18. When a sixth number is added to the set, the mean becomes 20. What is the sixth number?",answer:{kind:"text",accept:["30"]},explain:{en:"The first five sum to 5 × 18 = 90; all six sum to 6 × 20 = 120. The sixth number is 120 − 90 = 30.",ru:"Сумма первых пяти равна 5 · 18 = 90; сумма всех шести равна 6 · 20 = 120. Шестое число равно 120 − 90 = 30."},trap:{en:"The answer is not 20 + 2. Convert every mean into a total before comparing — averages do not add.",ru:"Ответ не 20 + 2. Переводи каждое среднее в сумму, прежде чем сравнивать: средние не складываются."}},{id:"m-dat-15",skill:"Problem-Solving and Data Analysis",topic:"Spread",difficulty:"medium",context:"Set X: 20, 30, 40, 50, 60\nSet Y: 35, 38, 40, 42, 45",stem:"Which statement about the two data sets is true?",options:["The sets have the same mean, and Set X has the greater standard deviation.","The sets have the same mean, and Set Y has the greater standard deviation.","Set X has the greater mean and the greater standard deviation.","The sets have the same mean and the same standard deviation."],answer:{kind:"choice",correct:0},explain:{en:"Both sets average 40. Set X spreads from 20 to 60 while Set Y stays between 35 and 45, so X's values sit further from the mean and its standard deviation is larger.",ru:"Среднее обоих наборов — 40. Set X разбросан от 20 до 60, а Set Y держится между 35 и 45, значит, значения X дальше от среднего и стандартное отклонение больше именно у X."},trap:{en:"Standard deviation is never about the size of the numbers, only their distance from the mean. Both sets are centred identically here.",ru:"Стандартное отклонение — не про величину чисел, а про их удалённость от среднего. Здесь центры наборов совпадают."}},{id:"m-dat-16",skill:"Problem-Solving and Data Analysis",topic:"Two-way tables",difficulty:"medium",context:"Students choosing a language elective:\n\n                Kazakh   Russian   Total\nGrade 10          54        66      120\nGrade 11          72        48      120\nTotal            126       114      240",stem:"If one of the students who chose Kazakh is selected at random, what is the probability that the student is in Grade 11?",answer:{kind:"text",accept:["4/7","72/126",".5714","0.5714"]},explain:{en:'The condition "who chose Kazakh" restricts the pool to the 126 students in that column. Of those, 72 are in Grade 11, so the probability is 72/126 = 4/7.',ru:"Условие «из выбравших казахский» сужает выборку до 126 человек в этом столбце. Из них 72 — в 11 классе, значит, вероятность равна 72/126 = 4/7."},trap:{en:"Dividing by 240 (the whole table) gives 72/240 = 0.3. A conditional probability uses the row or column named in the condition as its denominator.",ru:"Деление на 240 (всю таблицу) даёт 72/240 = 0,3. У условной вероятности в знаменателе — та строка или столбец, что названы в условии."}},{id:"m-dat-17",skill:"Problem-Solving and Data Analysis",topic:"Percent change",difficulty:"hard",stem:"The price of an item is increased by 25 percent and the new price is then decreased by 20 percent. Compared with the original price, the final price is",options:["5 percent greater.","5 percent less.","unchanged.","1 percent greater."],answer:{kind:"choice",correct:2},explain:{en:"Multiply the factors: 1.25 × 0.80 = 1.00. The 20 percent decrease is taken from the larger price, so it removes exactly what the increase added.",ru:"Перемножаем коэффициенты: 1,25 · 0,80 = 1,00. Снижение на 20% считается от уже увеличенной цены и убирает ровно то, что добавил рост."},trap:{en:"Adding and subtracting the percentages (+25 − 20 = +5) treats both as shares of the same base, which they are not.",ru:"Сложение и вычитание процентов (+25 − 20 = +5) считает их долями одной базы, а база разная."}},{id:"m-dat-18",skill:"Problem-Solving and Data Analysis",topic:"Rates and proportions",difficulty:"hard",stem:"One litre of sealant costs 2,400 tenge and covers 6 square metres of flooring. A workshop floor has a total area of A square metres. Which equation gives the cost C, in tenge, of the sealant needed to coat the floor twice?",options:["C = 800A","C = 400A","C = 1,200A","C = 4,800A"],answer:{kind:"choice",correct:0},explain:{en:"Two coats cover 2A square metres, needing 2A/6 = A/3 litres. The cost is 2,400 × A/3 = 800A.",ru:"Два слоя покрывают 2A квадратных метров, на это нужно 2A/6 = A/3 литра. Стоимость равна 2 400 · A/3 = 800A."},trap:{en:"C = 400A is the single-coat answer. Read whether the doubling applies to the area or to the price.",ru:"C = 400A — это ответ для одного слоя. Смотри, к чему относится удвоение: к площади или к цене."}},{id:"m-dat-19",skill:"Problem-Solving and Data Analysis",topic:"Unit rates",difficulty:"easy",stem:"A train travels 348 kilometres in 4 hours. At this same rate, how many kilometres will it travel in 7 hours?",answer:{kind:"text",accept:["609"]},explain:{en:"The rate is 348/4 = 87 kilometres per hour, so in 7 hours it covers 87 × 7 = 609 kilometres.",ru:"Скорость равна 348/4 = 87 километров в час, значит, за 7 часов будет 87 · 7 = 609 километров."}},{id:"m-dat-20",skill:"Problem-Solving and Data Analysis",topic:"Linear models in context",difficulty:"medium",context:"A line of best fit for a scatterplot relating x, the number of years since 2010, and y, the average monthly wage in a region in thousands of tenge, is given by y = 14.6x + 92.",stem:"Which of the following is the best interpretation of the number 14.6 in this context?",options:["The average monthly wage increased by about 14,600 tenge per year.","The average monthly wage in 2010 was about 14,600 tenge.","The average monthly wage increased by about 14.6 percent per year.","It took about 14.6 years for the average monthly wage to double."],answer:{kind:"choice",correct:0},explain:{en:"In y = mx + b, the slope m is the change in y per one-unit change in x. Here that is 14.6 thousand tenge for each additional year.",ru:"В y = mx + b наклон m — это изменение y при росте x на единицу. Здесь — 14,6 тысячи тенге за каждый следующий год."},trap:{en:"Option B describes the intercept 92, not the slope. Option C turns a constant amount into a percentage — a linear model adds, it does not multiply.",ru:"Вариант B описывает свободный член 92, а не наклон. Вариант C превращает постоянную сумму в процент, а линейная модель прибавляет, а не умножает."}},{id:"m-dat-21",skill:"Problem-Solving and Data Analysis",topic:"Sampling and inference",difficulty:"hard",context:"A researcher surveyed 400 randomly selected residents of a city with a population of 900,000. In the sample, 62 percent supported a proposed transport measure, with an associated margin of error of 4 percent at a 95 percent confidence level.",stem:"Which conclusion is best supported by these results?",options:["It is plausible that between 58 and 66 percent of all residents of the city support the measure.","Exactly 62 percent of all residents of the city support the measure.","Between 58 and 66 percent of the 400 surveyed residents support the measure.","If 400 more residents were surveyed, exactly 248 of them would support the measure."],answer:{kind:"choice",correct:0},explain:{en:"A margin of error gives a plausible interval for the whole population, not the sample. Because the sample was random, 62% ± 4% generalises to all residents.",ru:"Погрешность задаёт правдоподобный интервал для всей популяции, а не для выборки. Так как выборка случайна, 62% ± 4% переносится на всех жителей."},trap:{en:"Option C applies the interval to the sample, where the figure is known exactly. The interval exists precisely because the population figure is not known.",ru:"Вариант C применяет интервал к выборке, где значение известно точно. Интервал и нужен как раз потому, что значение по популяции неизвестно."}},{id:"m-dat-22",skill:"Problem-Solving and Data Analysis",topic:"Percent of a percent",difficulty:"medium",stem:"In a class of 32 students, 62.5 percent study French. Of the students who study French, 40 percent also study German. How many students in the class study both languages?",answer:{kind:"text",accept:["8"]},explain:{en:"French students: 0.625 × 32 = 20. Of those, 40 percent study German too: 0.40 × 20 = 8.",ru:"Французский изучают 0,625 · 32 = 20 человек. Из них немецкий изучают 40%: 0,40 · 20 = 8."},trap:{en:"Taking 40 percent of 32 gives 12.8. The second percentage is a share of the French group, not of the whole class.",ru:"40% от 32 дают 12,8. Второй процент берётся от группы «французский», а не от всего класса."}},{id:"m-dat-23",skill:"Problem-Solving and Data Analysis",topic:"Exponential versus linear growth",difficulty:"medium",context:"t (years):        0     1     2     3\nP (population):  1,200 1,440 1,728 2,074",stem:"Which type of model best fits the data in the table, and what is the associated constant?",options:["Exponential, with a growth factor of about 1.2 per year","Linear, with a slope of about 240 per year","Exponential, with a growth factor of about 1.44 per year","Linear, with a slope of about 291 per year"],answer:{kind:"choice",correct:0},explain:{en:"The successive ratios are constant — 1,440/1,200 = 1.2, 1,728/1,440 = 1.2, 2,074/1,728 ≈ 1.2 — while the differences (240, 288, 346) grow. Constant ratio means exponential.",ru:"Отношения соседних значений постоянны: 1 440/1 200 = 1,2, 1 728/1 440 = 1,2, 2 074/1 728 ≈ 1,2, — а разности (240, 288, 346) растут. Постоянное отношение означает экспоненту."},trap:{en:"The first difference really is 240, which makes the linear option look right until you check the next one. Test at least two gaps before deciding.",ru:"Первая разность действительно 240, и линейный вариант выглядит верным, пока не проверишь следующую. Проверяй хотя бы два интервала."}},{id:"m-dat-24",skill:"Geometry and Trigonometry",topic:"Volume",difficulty:"easy",stem:"A cylindrical water tank has a radius of 3 metres and a height of 5 metres. What is the volume of the tank, in cubic metres?",options:["45π","30π","75π","15π"],answer:{kind:"choice",correct:0},explain:{en:"The volume of a cylinder is πr²h = π(3²)(5) = 45π cubic metres.",ru:"Объём цилиндра равен πr²h = π · 3² · 5 = 45π кубометров."},trap:{en:"30π comes from using 2r instead of r². The radius is squared, not doubled.",ru:"30π получается, если взять 2r вместо r². Радиус возводится в квадрат, а не удваивается."}}],h=[{id:"m2-alg-01",skill:"Algebra",topic:"Systems of equations",difficulty:"easy",stem:"2x + 3y = 31\ny = x − 3\n\nWhat is the value of x in the solution to the given system of equations?",answer:{kind:"text",accept:["8"]},explain:{en:"Substitute the second equation into the first: 2x + 3(x − 3) = 31, so 5x − 9 = 31, giving 5x = 40 and x = 8.",ru:"Подставим второе уравнение в первое: 2x + 3(x − 3) = 31, отсюда 5x − 9 = 31, значит, 5x = 40 и x = 8."},trap:{en:"The question asks for x, not y. Having found x = 8 it is easy to compute y = 5 and grid that instead.",ru:"Спрашивают x, а не y. Найдя x = 8, легко по инерции посчитать y = 5 и вписать его."}},{id:"m2-alg-02",skill:"Algebra",topic:"Systems with no solution",difficulty:"medium",stem:"y = (2/5)x + 7\ny = kx − 4\n\nIn the given system, k is a constant. If the system has no solution, what is the value of k?",answer:{kind:"text",accept:["2/5",".4","0.4"]},explain:{en:"Two lines have no intersection exactly when they are parallel — equal slopes, different intercepts. So k = 2/5, and since 7 ≠ −4 the lines really are distinct.",ru:"Две прямые не пересекаются ровно тогда, когда они параллельны: равные наклоны, разные свободные члены. Значит, k = 2/5, а так как 7 ≠ −4, прямые действительно различны."}},{id:"m2-alg-03",skill:"Advanced Math",topic:"Sum and product of roots",difficulty:"hard",stem:"3x² − 12x + 7 = 0\n\nThe solutions to the given equation are p and q. What is the value of p + q?",answer:{kind:"text",accept:["4"]},explain:{en:"For ax² + bx + c = 0 the roots sum to −b/a. Here that is 12/3 = 4. The roots themselves are irrational, so solving for them wastes time.",ru:"Для ax² + bx + c = 0 сумма корней равна −b/a. Здесь это 12/3 = 4. Сами корни иррациональны, поэтому искать их — потеря времени."},trap:{en:"Reaching for the quadratic formula gives (12 ± √60)/6 and a messy addition. When the question asks for a sum or a product, use the coefficients.",ru:"Формула корней даёт (12 ± √60)/6 и грязное сложение. Если спрашивают сумму или произведение — работай с коэффициентами."}},{id:"m2-alg-04",skill:"Advanced Math",topic:"Function transformations",difficulty:"hard",stem:"The function g is defined by g(x) = f(x − 3) + 5. If the graph of f has its minimum at the point (2, −4), at which point does the graph of g have its minimum?",options:["(5, 1)","(−1, 1)","(5, −9)","(2, 1)"],answer:{kind:"choice",correct:0},explain:{en:"f(x − 3) shifts the graph 3 units right, and + 5 shifts it 5 units up. The minimum moves from (2, −4) to (2 + 3, −4 + 5) = (5, 1).",ru:"f(x − 3) сдвигает график на 3 вправо, а + 5 — на 5 вверх. Минимум переходит из (2, −4) в (2 + 3, −4 + 5) = (5, 1)."},trap:{en:"The sign inside the function is counter-intuitive: x − 3 moves the graph in the positive direction, not the negative one.",ru:"Знак внутри функции контринтуитивен: x − 3 сдвигает график в положительную сторону, а не в отрицательную."}},{id:"m2-alg-05",skill:"Advanced Math",topic:"Exponent equations",difficulty:"easy",stem:"3^(2x) = 81\n\nWhat is the value of x in the given equation?",answer:{kind:"text",accept:["2"]},explain:{en:"Write both sides with base 3: 81 = 3⁴, so 3^(2x) = 3⁴ and 2x = 4, giving x = 2.",ru:"Приведём обе части к основанию 3: 81 = 3⁴, значит, 3^(2x) = 3⁴ и 2x = 4, отсюда x = 2."}},{id:"m2-alg-06",skill:"Advanced Math",topic:"Rational exponents",difficulty:"medium",stem:"For x > 0, the expression x^(1/2) · x^(2/3) is equal to x^k. What is the value of k?",answer:{kind:"text",accept:["7/6"]},explain:{en:"Multiplying powers of the same base adds the exponents: 1/2 + 2/3 = 3/6 + 4/6 = 7/6.",ru:"При умножении степеней с одинаковым основанием показатели складываются: 1/2 + 2/3 = 3/6 + 4/6 = 7/6."},trap:{en:"Multiplying the exponents gives 1/3, which is the rule for a power of a power, not a product.",ru:"Умножение показателей даёт 1/3 — это правило для степени в степени, а не для произведения."}},{id:"m2-alg-07",skill:"Algebra",topic:"Systems solved for an expression",difficulty:"medium",stem:"5a + 2b = 26\n3a + 2b = 18\n\nWhat is the value of a + b?",answer:{kind:"text",accept:["7"]},explain:{en:"Subtracting the second equation from the first eliminates b: 2a = 8, so a = 4. Then 2b = 26 − 20 = 6, giving b = 3 and a + b = 7.",ru:"Вычитая второе уравнение из первого, убираем b: 2a = 8, значит, a = 4. Тогда 2b = 26 − 20 = 6, отсюда b = 3 и a + b = 7."}},{id:"m2-dat-01",skill:"Problem-Solving and Data Analysis",topic:"Percent change",difficulty:"hard",stem:"A shop's monthly revenue increased by 15 percent to 989,000 tenge. What was the revenue, in tenge, before the increase?",answer:{kind:"text",accept:["860000","860,000"]},explain:{en:"The new figure is 1.15 times the old one, so the old one is 989,000 / 1.15 = 860,000.",ru:"Новая величина — это 1,15 от старой, значит, старая равна 989 000 / 1,15 = 860 000."},trap:{en:"Taking 15 percent off 989,000 gives 840,650, which is wrong: the percentage was applied to the smaller original, not to the result.",ru:"Вычесть 15% из 989 000 даёт 840 650 — неверно: процент считался от меньшего исходного значения, а не от результата."}},{id:"m2-dat-02",skill:"Geometry and Trigonometry",topic:"Arc length",difficulty:"medium",stem:"A circle has a radius of 15. What is the length of an arc subtended by a central angle measuring 1.2 radians?",answer:{kind:"text",accept:["18"]},explain:{en:"Arc length is s = rθ when the angle is in radians: s = 15 × 1.2 = 18.",ru:"Длина дуги равна s = rθ, если угол в радианах: s = 15 · 1,2 = 18."},trap:{en:"The formula only works in radians. Converting 1.2 radians to degrees first and then using the degree formula is a longer road to the same place — and a common source of error.",ru:"Формула работает только с радианами. Перевести 1,2 радиана в градусы и считать по градусной формуле — более длинный путь и частый источник ошибок."}},{id:"m2-dat-03",skill:"Geometry and Trigonometry",topic:"Similar triangles",difficulty:"medium",stem:"Triangle ABC is similar to triangle DEF, with vertex A corresponding to D and B to E. If AB = 9, BC = 12 and DE = 15, what is the length of EF?",answer:{kind:"text",accept:["20"]},explain:{en:"The scale factor from ABC to DEF is DE/AB = 15/9 = 5/3. So EF = BC × 5/3 = 12 × 5/3 = 20.",ru:"Коэффициент подобия от ABC к DEF равен DE/AB = 15/9 = 5/3. Значит, EF = BC · 5/3 = 12 · 5/3 = 20."}},{id:"m2-dat-04",skill:"Problem-Solving and Data Analysis",topic:"Probability",difficulty:"hard",stem:"A box contains 7 red marbles and 5 blue marbles. Two marbles are drawn at random without replacement. What is the probability that both are red?",options:["7/22","49/144","7/12","1/2"],answer:{kind:"choice",correct:0},explain:{en:"The first draw is 7/12. After a red is removed, 6 reds remain out of 11, so the second is 6/11. Multiplying: 42/132 = 7/22.",ru:"Первое извлечение — 7/12. После изъятия красного остаётся 6 красных из 11, поэтому второе — 6/11. Перемножаем: 42/132 = 7/22."},trap:{en:'49/144 treats the draws as independent, which they are not — "without replacement" changes the second denominator and numerator.',ru:"49/144 считает извлечения независимыми, а они не независимы: «без возвращения» меняет и числитель, и знаменатель второго."}},{id:"m2-dat-05",skill:"Problem-Solving and Data Analysis",topic:"Mean",difficulty:"medium",stem:"The mean of six numbers is 25. Five of the numbers are 18, 22, 26, 30 and 34. What is the sixth number?",answer:{kind:"text",accept:["20"]},explain:{en:"All six sum to 6 × 25 = 150. The five given sum to 130, so the sixth is 150 − 130 = 20.",ru:"Сумма всех шести равна 6 · 25 = 150. Пять данных дают 130, значит, шестое равно 150 − 130 = 20."}},{id:"m2-dat-06",skill:"Algebra",topic:"Linear inequalities",difficulty:"medium",stem:"A delivery van can carry a maximum load of 900 kilograms and is already carrying 240 kilograms of equipment. Each box to be loaded weighs 22 kilograms. What is the greatest number of boxes that can be loaded?",answer:{kind:"text",accept:["30"]},explain:{en:"The remaining capacity is 900 − 240 = 660 kilograms, so 22n ≤ 660 gives n ≤ 30. The greatest whole number of boxes is 30.",ru:"Остаточная грузоподъёмность — 900 − 240 = 660 кг, значит, 22n ≤ 660 даёт n ≤ 30. Наибольшее целое число коробок — 30."},trap:{en:"Dividing 900 by 22 gives about 40 and ignores the equipment already on board.",ru:"Деление 900 на 22 даёт около 40 и игнорирует уже загруженное оборудование."}},{id:"m2-dat-07",skill:"Algebra",topic:"Absolute value",difficulty:"medium",stem:"|x − 4| < 9\n\nWhich of the following describes all solutions to the given inequality?",options:["−5 < x < 13","x < 13","x > −5","x < −5 or x > 13"],answer:{kind:"choice",correct:0},explain:{en:"An absolute value less than a number becomes a double inequality: −9 < x − 4 < 9. Adding 4 throughout gives −5 < x < 13.",ru:"Модуль меньше числа превращается в двойное неравенство: −9 < x − 4 < 9. Прибавив 4 ко всем частям, получаем −5 < x < 13."},trap:{en:"Option D is the answer to |x − 4| > 9. Less-than gives an interval between the bounds; greater-than gives the two rays outside them.",ru:"Вариант D — ответ для |x − 4| > 9. «Меньше» даёт промежуток между границами, «больше» — два луча за ними."}},{id:"m2-dat-08",skill:"Problem-Solving and Data Analysis",topic:"Line of best fit",difficulty:"medium",context:"A line of best fit for a scatterplot relating x, the age of a used car in years, and y, its value in hundreds of thousands of tenge, is given by y = −0.8x + 46.",stem:"According to the model, what is the predicted value, in hundreds of thousands of tenge, of a car that is 10 years old?",answer:{kind:"text",accept:["38"]},explain:{en:"Substitute x = 10: y = −0.8(10) + 46 = −8 + 46 = 38.",ru:"Подставим x = 10: y = −0,8 · 10 + 46 = −8 + 46 = 38."}},{id:"m2-dat-09",skill:"Geometry and Trigonometry",topic:"Volume",difficulty:"medium",stem:"A cone has a radius of 6 and a height of 14. What is the volume of the cone?",options:["168π","504π","84π","56π"],answer:{kind:"choice",correct:0},explain:{en:"The volume of a cone is (1/3)πr²h = (1/3)π(36)(14) = 168π.",ru:"Объём конуса равен (1/3)πr²h = (1/3)π · 36 · 14 = 168π."},trap:{en:"504π is the cylinder with the same base and height. A cone is one third of it — the factor is easy to drop.",ru:"504π — это цилиндр с тем же основанием и высотой. Конус втрое меньше, и множитель легко потерять."}},{id:"m2-dat-10",skill:"Geometry and Trigonometry",topic:"Special right triangles",difficulty:"easy",stem:"In a right triangle, one of the acute angles measures 30 degrees and the side opposite that angle has length 11. What is the length of the hypotenuse?",answer:{kind:"text",accept:["22"]},explain:{en:"In a 30-60-90 triangle the side opposite the 30° angle is half the hypotenuse, so the hypotenuse is 2 × 11 = 22.",ru:"В треугольнике 30-60-90 катет против угла 30° вдвое меньше гипотенузы, значит, гипотенуза равна 2 · 11 = 22."}},{id:"m2-alg-08",skill:"Advanced Math",topic:"Polynomial zeros",difficulty:"hard",stem:"The polynomial p is defined by p(x) = (x − 2)²(x + 5). How many distinct real zeros does p have?",answer:{kind:"text",accept:["2"]},explain:{en:"Setting each factor to zero gives x = 2 (from the squared factor) and x = −5. That is two distinct values, even though the polynomial has degree 3.",ru:"Приравняв каждый множитель к нулю, получаем x = 2 (из квадрата) и x = −5. Это два различных значения, хотя степень многочлена равна 3."},trap:{en:'The degree is 3, so there are three roots counted with multiplicity — but x = 2 is one distinct value repeated, and the question says "distinct".',ru:"Степень равна 3, то есть корней три с учётом кратности, но x = 2 — одно значение, повторённое дважды, а спрашивают «различных»."}}],c=[...i,...n,...a,...s].map(t.shuffleExamItem),l=[...o,...r,...h].map(t.shuffleExamItem);function d(e,t){let i=[...e];for(let e=i.length-1;e>0;e--){let a=Math.floor(t()*(e+1));[i[e],i[a]]=[i[a],i[e]]}return i}function u(e){return{id:e.id,exam:"sat",section:e.section,title:e.title,subtitle:{en:e.en,ru:e.ru},minutes:e.minutes,difficulty:e.difficulty,items:e.items}}let m=[u({id:"sat-rw-craft",section:"rw",title:"Craft, Structure and Ideas",minutes:40,difficulty:"medium",items:[...i,...n].map(t.shuffleExamItem),ru:"Слова в контексте, структура текста, главная мысль, работа с доказательствами и выводы.",en:"Words in context, text structure, central ideas, command of evidence and inferences."}),u({id:"sat-rw-conventions",section:"rw",title:"Conventions and Expression",minutes:38,difficulty:"medium",items:[...a,...s].map(t.shuffleExamItem),ru:"Пунктуация и границы предложений, согласование, связки и риторический синтез — самый быстрый раздел для роста балла.",en:"Punctuation and sentence boundaries, agreement, transitions and rhetorical synthesis — the fastest section to improve."}),u({id:"sat-math-algebra",section:"math",title:"Algebra and Advanced Math",minutes:35,difficulty:"hard",items:o.map(t.shuffleExamItem),ru:"Системы без решений и с бесконечным числом решений, дискриминант, показательные модели, дробные степени.",en:"Systems with no or infinite solutions, discriminants, exponential models and rational exponents."}),u({id:"sat-math-data",section:"math",title:"Data, Geometry and Trigonometry",minutes:50,difficulty:"hard",items:[...r,...h].map(t.shuffleExamItem),ru:"Перевод единиц, проценты, таблицы и вероятность, окружности, объёмы и тригонометрия прямоугольного треугольника.",en:"Unit conversion, percentages, tables and probability, circles, volumes and right-triangle trigonometry."})];e.s(["MIX_EASIER",0,{easy:.45,medium:.4,hard:.15},"MIX_HARDER",0,{easy:.1,medium:.35,hard:.55},"MIX_MIXED",0,{easy:.3,medium:.45,hard:.25},"SAT_BLUEPRINT",0,[{id:"rw1",section:"rw",stage:1,title:"Reading and Writing — Module 1",minutes:32,count:27},{id:"rw2",section:"rw",stage:2,title:"Reading and Writing — Module 2",minutes:32,count:27},{id:"m1",section:"math",stage:1,title:"Math — Module 1",minutes:35,count:22},{id:"m2",section:"math",stage:2,title:"Math — Module 2",minutes:35,count:22}],"SAT_BREAK_AFTER",0,"rw2","SAT_BREAK_MINUTES",0,10,"SAT_MATH_POOL",0,l,"SAT_RW_POOL",0,c,"SAT_SETS",0,m,"drawModule",0,function(e,t,i,a,n){let s=e.filter(e=>!a.has(e.id)),o={easy:d(s.filter(e=>"easy"===e.difficulty),n),medium:d(s.filter(e=>"medium"===e.difficulty),n),hard:d(s.filter(e=>"hard"===e.difficulty),n)},r=[];for(let e of["easy","medium","hard"]){let a=Math.round(t*i[e]);r.push(...o[e].splice(0,a))}let h=d([...o.easy,...o.medium,...o.hard],n);for(;r.length<t&&h.length>0;)r.push(h.shift());let c=new Map(e.map((e,t)=>[e.id,t]));return r.slice(0,t).sort((e,t)=>(c.get(e.id)??0)-(c.get(t.id)??0))},"poolFor",0,function(e){return"rw"===e?c:l},"satSetById",0,function(e){return m.find(t=>t.id===e)},"seededRandom",0,function(e){let t=e>>>0;return()=>(t=1664525*t+0x3c6ef35f>>>0)/0x100000000}],68394)}]);